1	"use client";
2	
3	import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
4	import { Icon } from "@/components/nx/Icon";
5	import {
6	  checkModUpdates,
7	  getModsOverview,
8	  panelDisableMod,
9	  panelEnableMod,
10	  panelInstallMod,
11	  panelRemoveMod,
12	  panelUpdateMod,
13	  previewModInstall,
14	  type InstallPreview,
15	  type ModsOverview,
16	  type PanelMod,
17	} from "@/lib/actions-mod-installs";
18	import { gamePower } from "@/lib/actions-game-control";
19	import type { ModLoad } from "@/lib/mod-load";
20	import type { Compat } from "@/lib/mods/types";
21	import type { BrowseCard } from "@/lib/mods-browse";
22	import { ModBrowser } from "@/components/customer/mods/browser/ModBrowser";
23	import { goPanelTab, modConfigFolder } from "@/lib/mods/manual-install";
24	
25	/**
26	 * Mods & Plugins — the real catalogue, searched server-side, installed by the
27	 * per-game installers in lib/mods/installers/*.
28	 *
29	 * What's on this tab and where each fact comes from:
30	 *  - the catalogue: GameMod rows for this game, searched/filtered/paged in the
31	 *    DB (all of them — Minecraft alone is 30k+), with a compatibility badge
32	 *    computed by the game's installer for THIS server's loader + version;
33	 *  - "what will be installed": a live dependency resolve against the mod's own
34	 *    source (Modrinth/Thunderstore/uMod/GitHub/Factorio portal) before the
35	 *    customer confirms;
36	 *  - progress: the GAME_MOD_SYNC job's own step/progress columns;
37	 *  - restart prompt: the last mod job's result vs. the last power job;
38	 *  - every number (downloads, size, dependencies) is the source's own, or
39	 *    absent — never estimated.
40	 *
41	 * A change the worker could not apply comes back as a failure with its reason.
42	 * There is no path on this tab that shows success the worker didn't report.
43	 */
44	
45	const SOURCE_LABEL: Record<string, string> = {
46	  modrinth: "Modrinth", spigotmc: "SpigotMC", hangar: "Hangar", curseforge: "CurseForge", steam_workshop: "Steam Workshop",
47	  umod: "uMod", github: "GitHub", nexus: "Nexus Mods", thunderstore: "Thunderstore", codefling: "Codefling", mod_io: "mod.io",
48	  vintagestory_moddb: "Vintage Story ModDB", factorio_portal: "Factorio Mod Portal", ficsit: "ficsit.app", reforger_workshop: "Arma Reforger Workshop",
49	};
50	
51	const PLUGIN_CATS = ["admin", "permission", "protection", "economy", "chat", "discord", "core", "utility", "clan", "rank", "teleport", "plugins"];
52	
53	function fileSize(bytes: number | null): string | null {
54	  if (!bytes || bytes <= 0) return null;
55	  return bytes >= 1024 ** 3 ? `${(bytes / 1024 ** 3).toFixed(1)} GB` : bytes >= 1024 * 1024 ? `${Math.round(bytes / 1024 / 1024)} MB` : `${Math.max(1, Math.round(bytes / 1024))} KB`;
56	}
57	
58	const STATE: Record<string, { label: string; cls: string }> = {
59	  INSTALLED: { label: "Installed", cls: "border-emerald-500/40 bg-emerald-500/10 text-emerald-300" },
60	  DISABLED: { label: "Disabled", cls: "border-white/20 bg-white/[0.06] text-tx-dim" },
61	  INSTALLING: { label: "Installing", cls: "border-sky-500/40 bg-sky-500/10 text-sky-300" },
62	  UPDATING: { label: "Updating", cls: "border-sky-500/40 bg-sky-500/10 text-sky-300" },
63	  ENABLING: { label: "Enabling", cls: "border-sky-500/40 bg-sky-500/10 text-sky-300" },
64	  DISABLING: { label: "Disabling", cls: "border-amber-500/40 bg-amber-500/10 text-amber-300" },
65	  REMOVING: { label: "Removing", cls: "border-amber-500/40 bg-amber-500/10 text-amber-300" },
66	  FAILED: { label: "Failed", cls: "border-red-500/40 bg-red-500/10 text-red-300" },
67	};
68	const PENDING = new Set(["INSTALLING", "UPDATING", "ENABLING", "DISABLING", "REMOVING"]);
69	
70	
71	const LOAD_STYLE: Record<string, { ring: string; ink: string; icon: string; label: string }> = {
72	  fine: { ring: "border-rim-hi bg-well", ink: "text-tx-dim", icon: "checkcircle", label: "Load looks fine" },
73	  watch: { ring: "border-sky-500/35 bg-sky-500/[0.07]", ink: "text-sky-300", icon: "warncircle", label: "Worth watching" },
74	  high: { ring: "border-amber-500/45 bg-amber-500/[0.09]", ink: "text-amber-300", icon: "warntriangle", label: "Heavy for this tier" },
75	};
76	
77	function LoadBanner({ load }: { load: ModLoad }) {
78	  if (load.count === 0) return null;
79	  const st = LOAD_STYLE[load.level];
80	  return (
81	    <div className={"flex flex-wrap items-start gap-3.5 rounded-[14px] border px-4 py-3.5 " + st.ring}>
82	      <span className={"grid h-[32px] w-[32px] flex-none place-items-center rounded-[10px] border border-white/10 bg-white/[0.05] " + st.ink}>
83	        <Icon name={st.icon} size={15} tone="inherit" />
84	      </span>
85	      <div className="min-w-0 flex-1">
86	        <p className={"text-[13px] font-bold " + st.ink}>{st.label}</p>
87	        <p className="mt-0.5 text-[12.5px] leading-relaxed text-tx-dim">{load.headline}</p>
88	        {load.advice && <p className="mt-1.5 max-w-[74ch] text-[12px] leading-relaxed text-tx-faint">{load.advice}</p>}
89	      </div>
90	      {load.percentOfRam !== null && (
91	        <div className="flex flex-none flex-col items-end">
92	          <span className={"num text-[19px] font-extrabold leading-none " + st.ink}>{load.percentOfRam}%</span>
93	          <span className="mt-1 text-[10px] font-bold uppercase tracking-[0.12em] text-tx-faint">of RAM, on disk</span>
94	        </div>
95	      )}
96	    </div>
97	  );
98	}
99	
100	/** What the install dialog needs — satisfied by an installed PanelMod or a browser card. */
101	type InstallTarget = { id: string; name: string; source: string; iconUrl: string | null; compat: Compat | null; impact: string; impactNote: string | null; url: string | null };
102	const fromCard = (m: BrowseCard): InstallTarget => ({ id: m.id, name: m.name, source: m.source, iconUrl: m.icon, compat: m.compat, impact: m.impact, impactNote: null, url: null });
103	
104	function ModIcon({ m, size = 40 }: { m: { iconUrl: string | null }; size?: number }) {
105	  return (
106	    <span className="grid flex-none place-items-center overflow-hidden rounded-[11px] border border-rim-hi bg-well" style={{ width: size, height: size }}>
107	      {m.iconUrl
108	        /* eslint-disable-next-line @next/next/no-img-element -- upstream mod icon */
109	        ? <img src={m.iconUrl} alt="" loading="lazy" className="h-full w-full object-cover" />
110	        : <Icon name="cube" size={Math.round(size * 0.42)} />}
111	    </span>
112	  );
113	}
114	
115	function Chip({ cls, icon, children, title }: { cls: string; icon?: string; children: React.ReactNode; title?: string }) {
116	  return (
117	    <span title={title} className={"inline-flex items-center gap-1 rounded-[6px] border px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide " + cls}>
118	      {icon && <Icon name={icon} size={10} tone="inherit" />}
119	      {children}
120	    </span>
121	  );
122	}
123	
124	const btnGhost = "rounded-[10px] border border-rim-hi bg-well px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:border-brand-400/45 hover:text-white disabled:opacity-50";
125	
126	export function ModsPanel({ serverId, scope }: { serverId: string; scope: "mods" | "plugins" }) {
127	  const [ov, setOv] = useState<ModsOverview | null>(null);
128	  const [fatal, setFatal] = useState<string | null>(null);
129	  const [error, setError] = useState<string | null>(null);
130	  const [tab, setTab] = useState<"browse" | "installed">("browse");
131	  const [total, setTotal] = useState<number | null>(null);
132	  const [refreshKey, setRefreshKey] = useState(0);
133	  const [confirm, setConfirm] = useState<InstallTarget | null>(null);
134	  const [busyId, setBusyId] = useState<string | null>(null);
135	  const [updates, setUpdates] = useState<Record<string, string | null> | null>(null);
136	  const [checking, setChecking] = useState(false);
137	  const [restarting, setRestarting] = useState(false);
138	  const [, start] = useTransition();
139	
140	  const loadOverview = useCallback(async () => {
141	    const r = await getModsOverview(serverId).catch(() => ({ error: "Couldn't load your mods." }) as { error: string });
142	    if ("view" in r && r.view) {
143	      setOv(r.view);
144	      setFatal(null);
145	    } else if ("error" in r && r.error) setFatal(r.error);
146	  }, [serverId]);
147	
148	  useEffect(() => { void loadOverview(); }, [loadOverview]);
149	
150	  // Plugins view = the catalogue's admin-ish categories (a filter, said plainly).
151	  const pluginCategory = useMemo(() => {
152	    if (scope !== "plugins" || !ov) return null;
153	    return ov.categories.find((c) => PLUGIN_CATS.some((k) => c.category.toLowerCase().includes(k)))?.category ?? null;
154	  }, [scope, ov]);
155	  // Follow the job while one is queued/running, then refresh the browser's results once.
156	  const active = !!ov?.job || (ov?.installed ?? []).some((m) => m.status && PENDING.has(m.status));
157	  const wasActive = useRef(false);
158	  useEffect(() => {
159	    if (!active) {
160	      if (wasActive.current) {
161	        wasActive.current = false;
162	        setRefreshKey((k) => k + 1);
163	      }
164	      return;
165	    }
166	    wasActive.current = true;
167	    const t = setInterval(() => void loadOverview(), 3000);
168	    return () => clearInterval(t);
169	  }, [active, loadOverview]);
170	
171	  const act = (m: { id: string }, op: "install" | "remove" | "update" | "disable" | "enable", ackClient = false) =>
172	    start(async () => {
173	      setBusyId(m.id);
174	      setConfirm(null);
175	      setError(null);
176	      const fn = op === "install"
177	        ? (sid: string, id: string) => panelInstallMod(sid, id, { ackClient })
178	        : { remove: panelRemoveMod, update: panelUpdateMod, disable: panelDisableMod, enable: panelEnableMod }[op];
179	      const r = await fn(serverId, m.id).catch(() => ({ error: "Couldn't reach the server." }) as { error: string });
180	      if (r && "error" in r && r.error) setError(r.error);
181	      await loadOverview();
182	      setRefreshKey((k) => k + 1);
183	      setBusyId(null);
184	    });
185	
186	  const restartNow = () =>
187	    start(async () => {
188	      setRestarting(true);
189	      setError(null);
190	      const r = await gamePower(serverId, "restart").catch(() => ({ ok: false as const, error: "Couldn't reach the server." }));
191	      if (!r.ok) setError(r.error);
192	      await loadOverview();
193	      setRestarting(false);
194	    });
195	
196	  const doCheckUpdates = () =>
197	    start(async () => {
198	      setChecking(true);
199	      const r = await checkModUpdates(serverId).catch(() => ({ error: "Couldn't check for updates." }) as { error: string });
200	      if ("updates" in r && r.updates) setUpdates(r.updates);
201	      else if ("error" in r && r.error) setError(r.error);
202	      setChecking(false);
203	    });
204	
205	  if (!ov && !fatal) {
206	    return <div className="rounded-[16px] border border-rim-hi bg-well px-6 py-16 text-center text-[13px] text-tx-dim">Loading mods…</div>;
207	  }
208	  if (!ov) {
209	    return (
210	      <div className="rounded-[16px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-6 py-14 text-center">
211	        <Icon name="cube" size={28} className="mx-auto" />
212	        <p className="mt-3 text-[14.5px] font-bold text-white">Mods aren&apos;t available for this game</p>
213	        <p className="mx-auto mt-1.5 max-w-[52ch] text-[12.5px] leading-relaxed text-tx-dim">{fatal}</p>
214	      </div>
215	    );
216	  }
217	
218	  const unavailable = ov.coverage.mode === "unavailable";
219	  const installedVisible = ov.installed.filter((m) => m.status !== "REMOVED");
220	
221	  return (
222	    <div className="flex flex-col gap-4">
223	      {/* ── banner ───────────────────────────────────────────────────── */}
224	      <div className="nx-dark-island overflow-hidden rounded-[17px] border border-[#7b3fef]/40 bg-[linear-gradient(140deg,rgba(90,40,200,.35),rgba(20,36,110,.28)_58%,rgba(4,12,34,.5))] p-4 sm:p-5">
225	        <div className="flex flex-wrap items-start gap-4 sm:gap-5">
226	          <span className="grid h-[48px] w-[48px] flex-none place-items-center rounded-[14px] border border-white/15 bg-white/10">
227	            <Icon name="cube" size={21} tone="inherit" className="text-fuchsia-300" />
228	          </span>
229	          <div className="min-w-0 flex-1">
230	            <div className="flex flex-wrap items-center gap-2">
231	              <h2 className="text-[19px] font-extrabold tracking-[-0.02em] text-white">Mods &amp; Plugins</h2>
232	              {unavailable ? (
233	                <Chip cls="border-white/20 bg-white/[0.07] text-white/70">Manual install</Chip>
234	              ) : (
235	                <Chip cls="border-cyan-400/40 bg-cyan-400/10 text-cyan-200" icon="bolt">One-click</Chip>
236	              )}
237	            </div>
238	            <p className="mt-1.5 max-w-[68ch] text-[12.5px] leading-relaxed text-white/75">
239	              {unavailable
240	                ? ov.coverage.text
241	                : <>Search the full {ov.familyName} catalogue and install in one click. {ov.coverage.mode === "engine" ? <>We fetch the right build for your server from the mod&apos;s own source, check it, pull in its dependencies and back up anything it changes. </> : null}<span className="text-white/55">{ov.coverage.text}</span> Mods marked <strong className="font-semibold text-white/80">Manual install</strong> aren&apos;t one-click: each one explains how to add it yourself.</>}
242	            </p>
243	            <p className="mt-2 flex flex-wrap items-center gap-2 text-[11.5px] text-white/60">
244	              <span className="rounded-[6px] border border-white/15 bg-white/[0.07] px-2 py-0.5 font-semibold text-white/85">
245	                {ov.variant ?? "server"}{ov.gameVersion ? ` · ${ov.gameVersion}` : ""}
246	              </span>
247	              compatibility is checked against this
248	            </p>
249	          </div>
250	          <dl className="flex flex-none gap-6">
251	            <div className="flex flex-col">
252	              <dt className="text-[10px] font-bold uppercase tracking-[0.14em] text-white/50">Installed</dt>
253	              <dd className="num text-[22px] font-extrabold leading-none text-white">{installedVisible.length}</dd>
254	            </div>
255	            <div className="flex flex-col">
256	              <dt className="text-[10px] font-bold uppercase tracking-[0.14em] text-white/50">Catalogue</dt>
257	              <dd className="num text-[22px] font-extrabold leading-none text-white">{ov.catalogTotal.toLocaleString()}</dd>
258	            </div>
259	          </dl>
260	        </div>
261	      </div>
262	
263	      {/* ── job progress ─────────────────────────────────────────────── */}
264	      {ov.job && (
265	        <div className="rounded-[14px] border border-sky-500/35 bg-sky-500/[0.07] px-4 py-3" role="status" aria-live="polite">
266	          <div className="flex items-center gap-2.5">
267	            <Icon name="refresh" size={14} tone="inherit" className="animate-spin text-sky-300" />
268	            <p className="min-w-0 flex-1 truncate text-[12.5px] font-semibold text-sky-200">
269	              {ov.job.status === "QUEUED" ? "Queued — waiting for the server to be free" : ov.job.step ?? "Working…"}
270	            </p>
271	            <span className="num text-[12px] font-bold text-sky-300">{ov.job.progress}%</span>
272	          </div>
273	          <div className="mt-2 h-[5px] overflow-hidden rounded-full bg-white/[0.08]">
274	            <div className="h-full rounded-full bg-[linear-gradient(90deg,#3b6be8,#7b3fef)] transition-all duration-700" style={{ width: `${Math.max(4, ov.job.progress)}%` }} />
275	          </div>
276	        </div>
277	      )}
278	
279	      {/* ── restart prompt ───────────────────────────────────────────── */}
280	      {!ov.job && ov.restart.required && (
281	        <div className="flex flex-wrap items-center gap-3 rounded-[14px] border border-amber-500/45 bg-amber-500/[0.09] px-4 py-3.5">
282	          <Icon name="warntriangle" size={16} tone="inherit" className="text-amber-300" />
283	          <div className="min-w-0 flex-1">
284	            <p className="text-[13px] font-bold text-amber-200">Restart to load your mod changes</p>
285	            {ov.restart.changed.length > 0 && (
286	              <p className="mt-0.5 line-clamp-2 text-[12px] text-amber-200/75">{ov.restart.changed.slice(0, 6).join(" · ")}</p>
287	            )}
288	          </div>
289	          <button type="button" onClick={restartNow} disabled={restarting || !ov.serverRunning} className="nx-cta px-4 py-2 text-[12.5px] disabled:opacity-50">
290	            {restarting ? "Restarting…" : "Restart now"}
291	          </button>
292	        </div>
293	      )}
294	
295	      <LoadBanner load={ov.load} />
296	
297	      {error && (
298	        <p className="rounded-[11px] border border-red-500/35 bg-red-500/10 px-3.5 py-2.5 text-[12.5px] text-red-300" role="alert">{error}</p>
299	      )}
300	
301	      {/* ── tabs ─────────────────────────────────────────────────────── */}
302	      <div className="flex flex-wrap items-center gap-2.5">
303	        <div className="flex gap-1 rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.72)] p-1">
304	          {([["browse", total === null ? "Browse" : `Browse (${total.toLocaleString()})`], ["installed", `Installed (${installedVisible.length})`]] as const).map(([k, label]) => (
305	            <button key={k} type="button" onClick={() => setTab(k)} aria-pressed={tab === k}
306	              className={"rounded-[8px] px-3.5 py-1.5 text-[12.5px] font-semibold transition " + (tab === k ? "bg-[#7b3fef]/25 text-white" : "text-tx-dim hover:text-white")}>
307	              {label}
308	            </button>
309	          ))}
310	        </div>
311	        {tab === "installed" && ov.coverage.canUpdate && installedVisible.length > 0 && (
312	          <button type="button" onClick={doCheckUpdates} disabled={checking} className={btnGhost + " ml-auto flex items-center gap-1.5"}>
313	            <Icon name="refresh2" size={12} tone="inherit" /> {checking ? "Checking…" : "Check for updates"}
314	          </button>
315	        )}
316	      </div>
317	
318	      {tab === "browse" ? (
319	        <ModBrowser
320	          serverId={serverId}
321	          scope={scope}
322	          unavailable={unavailable}
323	          jobActive={!!ov.job}
324	          refreshKey={refreshKey}
325	          defaultCategory={pluginCategory}
326	          catalogTotal={ov.catalogTotal}
327	          onInstall={(m) => setConfirm(fromCard(m))}
328	          onAct={(modId, op) => (op === "install" ? undefined : act({ id: modId }, op))}
329	          onTotal={setTotal}
330	        />
331	      ) : installedVisible.length === 0 ? (
332	        <p className="rounded-[14px] border border-rim-hi bg-well px-5 py-10 text-center text-[12.5px] text-tx-faint">Nothing installed yet — find something in Browse.</p>
333	      ) : (
334	        <div className="flex flex-col gap-2">
335	          {installedVisible.map((m) => (
336	            <InstalledRow key={m.id} m={m} ov={ov} busy={busyId === m.id || !!ov.job} latest={updates?.[m.id]}
337	              onAct={(op) => act(m, op)} />
338	          ))}
339	        </div>
340	      )}
341	
342	      <p className="text-[11.5px] leading-relaxed text-tx-faint">
343	        Anything not in the catalogue can still be installed by hand: upload it in the <strong className="text-tx-dim">Files</strong> tab and restart from <strong className="text-tx-dim">Console</strong>. Before changing files we keep a backup on your server in <span className="font-mono text-tx-dim">/root/.nxeon-mods/backups</span>.
344	      </p>
345	
346	      {confirm && <InstallDialog serverId={serverId} mod={confirm} load={ov.load} onCancel={() => setConfirm(null)} onConfirm={(ack) => act(confirm, "install", ack)} />}
347	    </div>
348	  );
349	}
350	
351	function InstalledRow({ m, ov, busy, latest, onAct }: { m: PanelMod; ov: ModsOverview; busy: boolean; latest: string | null | undefined; onAct: (op: "remove" | "update" | "disable" | "enable") => void }) {
352	  const st = m.status ? STATE[m.status] : null;
353	  const pending = !!m.status && PENDING.has(m.status);
354	  const hasUpdate = !!latest && !!m.version && latest !== m.version;
355	  const cfg = modConfigFolder(ov.family, ov.variant);
356	  return (
357	    <div className="flex flex-col gap-2 rounded-[14px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.5),rgba(2,7,20,.62))] p-3.5 sm:flex-row sm:items-center">
358	      <div className="flex min-w-0 flex-1 items-center gap-3">
359	        <ModIcon m={m} size={36} />
360	        <div className="min-w-0">
361	          <div className="flex flex-wrap items-center gap-1.5">
362	            <span className="truncate text-[13.5px] font-bold text-white">{m.name}</span>
363	            {st && <Chip cls={st.cls}>{st.label}</Chip>}
364	            {hasUpdate && <Chip cls="border-cyan-400/40 bg-cyan-400/10 text-cyan-200">Update: {latest}</Chip>}
365	          </div>
366	          <p className="mt-0.5 truncate text-[11.5px] text-tx-faint">
367	            {m.version ? `v${m.version} · ` : ""}{SOURCE_LABEL[m.source] ?? m.source}
368	            {latest === null && m.version ? " · couldn't check for updates" : latest && !hasUpdate ? " · up to date" : ""}
369	          </p>
370	          {m.error && <p className="mt-1 text-[11.5px] leading-snug text-red-300">{m.error}</p>}
371	        </div>
372	      </div>
373	      <div className="flex flex-none flex-wrap items-center gap-2">
374	        {ov.coverage.canUpdate && m.status === "INSTALLED" && (
375	          <button type="button" disabled={busy || pending} onClick={() => onAct("update")} className={btnGhost}>Update</button>
376	        )}
377	        {ov.coverage.canToggle && m.status === "INSTALLED" && (
378	          <button type="button" disabled={busy || pending} onClick={() => onAct("disable")} className={btnGhost}>Disable</button>
379	        )}
380	        {ov.coverage.canToggle && m.status === "DISABLED" && (
381	          <button type="button" disabled={busy || pending} onClick={() => onAct("enable")} className={btnGhost}>Enable</button>
382	        )}
383	        {(m.status === "INSTALLED" || m.status === "DISABLED" || m.status === "FAILED") && (
384	          <button type="button" disabled={busy || pending} onClick={() => onAct("remove")}
