1	/**
2	 * The install engine every lib/mods/installers/* family shares.
3	 *
4	 * It owns everything that must be the same for every game: the per-server
5	 * state file on the guest, dependency reference counting, conflict
6	 * detection, backups, staged writes with rollback, idempotent re-runs, and
7	 * enable/disable/update/uninstall. Installers only answer "where", "which
8	 * build" and "which files".
9	 *
10	 * STATE lives ON THE GUEST at /root/.nxeon-mods/state.json, not in our DB:
11	 * it is the record of which files Nxeon itself put on that disk, so it has to
12	 * travel with the disk (a restored backup, a customer who deleted things by
13	 * hand). The DB's ServerMod row stays the customer-facing desired state; the
14	 * worker reconciles the two. Nothing outside the state file is ever deleted.
15	 *
16	 * Concurrency: the worker never runs two jobs for the same server at once
17	 * (worker/index.ts lock key = serverId) and the portal refuses to queue a
18	 * second while one is in flight, so the state file has a single writer.
19	 */
20	import { createHash } from "node:crypto";
21	import type { GuestFs } from "./guest-fs";
22	import { isWithin } from "./paths";
23	import { FetchError, type Fetcher } from "./safe-fetch";
24	import type { MirrorLookup } from "./mirror";
25	import type { CatalogFacts, FamilyInstaller, InstallerCtx, Layout, OpResult, PlacedFile, ResolvedPackage, ServerFacts } from "./types";
26	
27	export const STATE_DIR = "/root/.nxeon-mods";
28	export const STATE_PATH = `${STATE_DIR}/state.json`;
29	const BACKUP_DIR = `${STATE_DIR}/backups`;
30	const DISABLED_DIR = `${STATE_DIR}/disabled`;
31	const KEEP_BACKUPS = 5;
32	/** Ceiling on what one operation may download in total (all packages). */
33	export const MAX_OP_BYTES = 512 * 1024 * 1024;
34	/** Ceiling on a single downloaded file. */
35	export const MAX_FILE_BYTES = 256 * 1024 * 1024;
36	
37	export type FileRec = { path: string; sha256: string; size: number };
38	export type PkgState = {
39	  key: string;
40	  name: string;
41	  version: string;
42	  versionId: string | null;
43	  files: FileRec[];
44	  /** GameMod ids that need this package (directly, or as a dependency). */
45	  roots: string[];
46	  requires: string[];
47	  incompatible: { key: string; name: string }[];
48	  disabled: boolean;
49	  installedAt: string;
50	  updatedAt: string;
51	};
52	export type GuestState = {
53	  v: 1;
54	  family: string;
55	  packages: Record<string, PkgState>;
56	  /** GameMod id → the package key it installed as. */
57	  roots: Record<string, { key: string; name: string }>;
58	};
59	
60	export function emptyState(family: string): GuestState {
61	  return { v: 1, family, packages: {}, roots: {} };
62	}
63	
64	export async function loadState(fs: GuestFs, family: string): Promise<GuestState> {
65	  const raw = await fs.readFile(STATE_PATH, 8 * 1024 * 1024);
66	  if (!raw) return emptyState(family);
67	  try {
68	    const s = JSON.parse(raw.toString("utf8")) as GuestState;
69	    if (s && s.v === 1 && s.packages && s.roots) return s;
70	  } catch {
71	    /* fall through */
72	  }
73	  throw new Error("This server's mod state file (/root/.nxeon-mods/state.json) is unreadable — nothing was changed. Contact support.");
74	}
75	
76	async function saveState(fs: GuestFs, s: GuestState): Promise<void> {
77	  const tmp = `${STATE_PATH}.nxeon-part`;
78	  await fs.writeFile(tmp, Buffer.from(JSON.stringify(s, null, 2) + "\n"));
79	  await fs.rename(tmp, STATE_PATH);
80	}
81	
82	const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");
83	const stamp = (d: Date) => d.toISOString().replace(/[:.]/g, "-");
84	const safeKey = (k: string) => k.replace(/[^A-Za-z0-9._-]/g, "_").slice(0, 120);
85	
86	/** Which package (other than `exceptKey`) claims `path`. */
87	export function ownerOf(s: GuestState, path: string, exceptKey?: string): PkgState | null {
88	  for (const p of Object.values(s.packages)) {
89	    if (p.key === exceptKey) continue;
90	    if (p.files.some((f) => f.path === path)) return p;
91	  }
92	  return null;
93	}
94	
95	export type EngineDeps = {
96	  fs: GuestFs;
97	  fetcher: Fetcher;
98	  mirror?: MirrorLookup | null;
99	  now?: () => Date;
100	  /** Progress callback (job step text + percent). */
101	  progress?: (step: string, pct: number) => void | Promise<void>;
102	};
103	
104	async function download(pkg: ResolvedPackage, deps: EngineDeps): Promise<{ bytes: Buffer; from: "mirror" | "upstream" | "prefetched" }> {
105	  if (pkg.prefetched) return { bytes: pkg.prefetched, from: "prefetched" };
106	  if (deps.mirror) {
107	    const hit = await deps.mirror(pkg.file);
108	    if (hit) return { bytes: hit, from: "mirror" };
109	  }
110	  if (pkg.file.size != null && pkg.file.size > MAX_FILE_BYTES) {
111	    throw new FetchError(`${pkg.name} is ${Math.round(pkg.file.size / 1048576)} MB — over the ${MAX_FILE_BYTES / 1048576} MB one-click limit`, "size");
112	  }
113	  const r = await deps.fetcher(pkg.file.url, {
114	    maxBytes: MAX_FILE_BYTES,
115	    timeoutMs: 180_000,
116	    expect: pkg.file.hashes,
117	    headers: pkg.file.headers,
118	  });
119	  return { bytes: r.bytes, from: "upstream" };
120	}
121	
122	async function detectOrFail(installer: FamilyInstaller, fs: GuestFs, server: ServerFacts, mod: CatalogFacts | null): Promise<Layout> {
123	  const det = await installer.detect(fs, server, mod);
124	  if ("error" in det) throw new UserFacing(det.error);
125	  return det;
126	}
127	
128	/** An error whose message is safe and meant for the customer. */
129	export class UserFacing extends Error {}
130	
131	function failure(e: unknown): { ok: false; error: string } {
132	  if (e instanceof UserFacing) return { ok: false, error: e.message };
133	  if (e instanceof FetchError) return { ok: false, error: `Download refused: ${e.message}.` };
134	  const m = e instanceof Error ? e.message : String(e);
135	  return { ok: false, error: m.length > 300 ? m.slice(0, 300) + "…" : m };
136	}
