143	/** Copy `paths` (those that exist) into a fresh backup folder. Returns path→backup copy. */
144	async function backup(fs: GuestFs, label: string, paths: string[], now: Date): Promise<Map<string, string>> {
145	  const out = new Map<string, string>();
146	  if (paths.length === 0) return out;
147	  const dir = `${BACKUP_DIR}/${stamp(now)}-${safeKey(label)}`;
148	  for (const p of paths) {
149	    const st = await fs.stat(p);
150	    if (!st || st.type !== "file") continue;
151	    const dest = `${dir}${p}`;
152	    await fs.copy(p, dest);
153	    out.set(p, dest);
154	  }
155	  if (await fs.stat(STATE_PATH)) await fs.copy(STATE_PATH, `${dir}/state.json`);
156	  await pruneBackups(fs);
157	  return out;
158	}
