162	/**
163	 * Install (or update) a catalogue mod and its required dependencies.
164	 * Idempotent: running it again with nothing new upstream changes nothing.
165	 */
166	export async function installOrUpdate(
167	  installer: FamilyInstaller,
168	  mod: CatalogFacts,
169	  server: ServerFacts,
170	  deps: EngineDeps,
171	  mode: "install" | "update" = "install",
172	): Promise<OpResult> {
173	  const fs = deps.fs;
174	  const now = (deps.now ?? (() => new Date()))();
175	  try {
176	    await deps.progress?.("Checking your server", 5);
177	    const layout = await detectOrFail(installer, fs, server, mod);
178	    const state = await loadState(fs, server.family);
179	    const ctx: InstallerCtx = { server, layout, fetcher: deps.fetcher };
180	
181	    await deps.progress?.(`Resolving ${mod.name} and its dependencies`, 15);
182	    const res = await installer.resolve(mod, ctx);
183	    if ("error" in res) return { ok: false, error: res.error };
184	    const pkgs = res.packages;
185	    const rootPkg = pkgs[pkgs.length - 1];
186	    if (!rootPkg || !rootPkg.root) return { ok: false, error: "Resolver returned no package for this mod." };
187	
188	    // A disabled mod is enabled again, not reinstalled behind the customer's back.
189	    const prevRoot = state.roots[mod.id];
190	    if (prevRoot && state.packages[prevRoot.key]?.disabled && mode === "install") {
191	      return { ok: false, error: `${mod.name} is installed but disabled — enable it instead.` };
192	    }
193	
194	    // ── declared incompatibilities, both directions ─────────────────────────
195	    const incoming = new Set(pkgs.map((p) => p.key));
196	    for (const p of pkgs) {
197	      for (const bad of p.incompatible) {
198	        const have = state.packages[bad.key];
199	        if (have && !have.disabled && !incoming.has(bad.key)) {
200	          return { ok: false, error: `${p.name} is incompatible with ${have.name}, which is installed — remove ${have.name} first.` };
201	        }
202	      }
203	    }
204	    for (const have of Object.values(state.packages)) {
205	      if (have.disabled) continue;
206	      const clash = have.incompatible.find((b) => incoming.has(b.key));
207	      if (clash) return { ok: false, error: `${have.name} (installed) declares it is incompatible with ${clash.name} — nothing was installed.` };
208	    }
209	
210	    // ── download + place, nothing written yet ───────────────────────────────
211	    const writes: Write[] = [];
212	    const notes = [...res.notes];
213	    let total = 0;
214	    let i = 0;
215	    for (const pkg of pkgs) {
216	      i++;
217	      const prev = state.packages[pkg.key] ?? null;
218	      if (prev && prev.version === pkg.version && (await filesIntact(fs, prev))) continue; // already there — idempotent
219	      await deps.progress?.(`Downloading ${pkg.name} ${pkg.version}`, 15 + Math.round((60 * i) / pkgs.length));
220	      const dl = await download(pkg, deps);
221	      total += dl.bytes.length;
222	      if (total > MAX_OP_BYTES) return { ok: false, error: `This install would download more than ${MAX_OP_BYTES / 1048576} MB — too large for one click.` };
223	      const placed = await installer.place(pkg, dl.bytes, ctx);
224	      if ("error" in placed) return { ok: false, error: placed.error };
225	      if (placed.length === 0) return { ok: false, error: `${pkg.name} ${pkg.version} contains nothing this server can load.` };
226	      for (const f of placed) {
227	        if (!isWithin(layout.base, f.path)) return { ok: false, error: `${pkg.name} tried to write outside the game folder — refused.` };
228	      }
229	      if (dl.from === "mirror") notes.push(`${pkg.name} came from the NX Labs mirror (checksum verified).`);
230	      writes.push({ pkg, files: placed, prev });
231	    }
232	
233	    const legacy = (installer.legacyPaths?.(mod, layout) ?? []).filter((p) => isWithin(layout.base, p));
234	
235	    // ── conflicts against files we don't own ───────────────────────────────
236	    const overwrite: string[] = [];
237	    for (const w of writes) {
238	      const prevPaths = new Set(w.prev?.files.map((f) => f.path) ?? []);
239	      for (const f of w.files) {
240	        const other = ownerOf(state, f.path, w.pkg.key);
241	        if (other) {
242	          const rec = other.files.find((x) => x.path === f.path)!;
243	          if (rec.sha256 === sha256(f.data)) continue; // byte-identical shared file — fine
244	          return { ok: false, error: `${w.pkg.name} would overwrite ${f.path}, which belongs to ${other.name} — nothing was changed.` };
245	        }
246	        if (prevPaths.has(f.path) || legacy.includes(f.path)) { overwrite.push(f.path); continue; }
247	        const st = await fs.stat(f.path);
248	        if (!st) continue;
249	        if (st.type === "dir") return { ok: false, error: `${f.path} already exists as a folder — nothing was changed.` };
250	        if (f.overwrite === "backup") { overwrite.push(f.path); continue; }
251	        const cur = await fs.readFile(f.path);
252	        if (cur && sha256(cur) === sha256(f.data)) continue; // same file already there (installed by hand) — adopt it
253	        return {
254	          ok: false,
255	          error: `${f.path} already exists and wasn't installed by Nxeon (added by hand?). Remove or rename it in Files, then try again — nothing was changed.`,
256	        };
257	      }
258	    }
259	
260	    // Files of the previous version that the new version no longer ships.
261	    const stale: string[] = [];
262	    for (const w of writes) {
263	      if (!w.prev) continue;
264	      const keep = new Set(w.files.map((f) => f.path));
265	      for (const f of w.prev.files) if (!keep.has(f.path) && !ownerOf(state, f.path, w.pkg.key)) stale.push(f.path);
266	    }
267	
268	    // Nothing to do at all → idempotent success, no restart needed.
269	    const existingLegacy: string[] = [];
270	    for (const p of legacy) {
271	      // A "legacy" path the engine itself now owns (same filename) is not legacy.
272	      if (ownerOf(state, p) || writes.some((w) => w.files.some((f) => f.path === p))) continue;
273	      if (await fs.stat(p)) existingLegacy.push(p);
274	    }
275	    if (writes.length === 0 && existingLegacy.length === 0) {
276	      addRoots(state, pkgs, mod);
277	      await saveState(fs, state);
278	      return { ok: true, version: rootPkg.version, restartRequired: false, changed: [], notes: [...notes, `${mod.name} ${rootPkg.version} is already installed and up to date.`] };
279	    }
280	
281	    // ── backup, then staged write ───────────────────────────────────────────
282	    await deps.progress?.("Backing up files that will change", 80);
283	    const backups = await backup(fs, mod.slug, [...overwrite, ...stale, ...existingLegacy], now);
284	
285	    await deps.progress?.("Writing files to your server", 88);
286	    const written: string[] = [];
287	    const created: string[] = [];
288	    try {
289	      for (const w of writes) {
290	        for (const f of w.files) {
291	          const existed = !!(await fs.stat(f.path));
292	          const part = `${f.path}.nxeon-part`;
293	          await fs.writeFile(part, f.data);
294	          await fs.rename(part, f.path);
295	          written.push(f.path);
296	          if (!existed) created.push(f.path);
297	        }
298	      }
299	      for (const p of stale) await fs.remove(p);
300	      for (const p of existingLegacy) if (!written.includes(p)) await fs.remove(p);
301	
302	      // State: record exactly what we wrote.
303	      for (const w of writes) {
304	        const prev = w.prev;
305	        state.packages[w.pkg.key] = {
306	          key: w.pkg.key,
307	          name: w.pkg.name,
308	          version: w.pkg.version,
309	          versionId: w.pkg.versionId ?? null,
310	          files: w.files.map((f) => ({ path: f.path, sha256: sha256(f.data), size: f.data.length })),
311	          roots: prev?.roots ?? [],
312	          requires: w.pkg.requires,
313	          incompatible: w.pkg.incompatible,
314	          disabled: false,
315	          installedAt: prev?.installedAt ?? now.toISOString(),
316	          updatedAt: now.toISOString(),
317	        };
318	      }
319	      addRoots(state, pkgs, mod);
320	
321	      if (installer.configure) {
322	        const edits = await installer.configure(fs, layout, enabledList(state), allList(state));
323	        for (const e of edits) {
324	          if (!isWithin(layout.base, e.path)) continue;
325	          if (!backups.has(e.path) && (await fs.stat(e.path))) await backup(fs, `${mod.slug}-config`, [e.path], now);
326	          await fs.writeFile(`${e.path}.nxeon-part`, e.data);
327	          await fs.rename(`${e.path}.nxeon-part`, e.path);
328	        }
329	      }
330	      await saveState(fs, state);
331	    } catch (e) {
332	      // Roll back: new files out, overwritten files back from the backup.
333	      for (const p of created) await fs.remove(p).catch(() => {});
334	      for (const [orig, copy] of backups) await fs.copy(copy, orig).catch(() => {});
335	      for (const w of writes) for (const f of w.files) await fs.remove(`${f.path}.nxeon-part`).catch(() => {});
336	      const why = failure(e).error;
337	      return { ok: false, error: `Writing to your server failed and the change was rolled back: ${why}` };
338	    }
339	    await fs.chownLike(layout.base, [...new Set(written.map((p) => p.split("/").slice(0, -1).join("/")))].filter((d) => isWithin(layout.base, d)));
340	
341	    const changed = writes.map((w) =>
342	      w.prev ? `updated ${w.pkg.name} ${w.prev.version} → ${w.pkg.version}` : `${w.pkg.root ? "installed" : "added dependency"} ${w.pkg.name} ${w.pkg.version}`,
343	    );
344	    if (existingLegacy.length) changed.push(`replaced ${existingLegacy.length} file(s) from the older Nxeon installer`);
345	    return { ok: true, version: rootPkg.version, restartRequired: installer.restartRequired, changed, notes };
346	  } catch (e) {
347	    return failure(e);
348	  }
349	}
