351	async function filesIntact(fs: GuestFs, p: PkgState): Promise<boolean> {
352	  if (p.disabled) return true;
353	  for (const f of p.files) {
354	    const st = await fs.stat(f.path);
355	    if (!st || st.type !== "file" || st.size !== f.size) return false;
356	  }
357	  return p.files.length > 0;
358	}
