360	function addRoots(state: GuestState, pkgs: ResolvedPackage[], mod: CatalogFacts) {
361	  const root = pkgs[pkgs.length - 1];
362	  state.roots[mod.id] = { key: root.key, name: mod.name };
363	  for (const p of pkgs) {
364	    const st = state.packages[p.key];
365	    if (st && !st.roots.includes(mod.id)) st.roots.push(mod.id);
366	  }
367	}
