369	function enabledList(s: GuestState) {
370	  return Object.values(s.packages).filter((p) => !p.disabled).map((p) => ({ key: p.key, name: p.name, version: p.version }));
371	}
372	function allList(s: GuestState) {
373	  return Object.values(s.packages).map((p) => ({ key: p.key, name: p.name }));
374	}
