473	/** Disable (move aside / native flag) or re-enable an installed mod. */
474	export async function setDisabled(installer: FamilyInstaller, mod: CatalogFacts, server: ServerFacts, deps: EngineDeps, disabled: boolean): Promise<OpResult> {
475	  const fs = deps.fs;
476	  try {
477	    const layout = await detectOrFail(installer, fs, server, mod);
478	    const state = await loadState(fs, server.family);
479	    const r = state.roots[mod.id];
480	    const p = r ? state.packages[r.key] : null;
481	    if (!p) return { ok: false, error: `${mod.name} isn't installed by Nxeon on this server, so it can't be ${disabled ? "disabled" : "enabled"} here.` };
482	    if (p.disabled === disabled) return { ok: true, restartRequired: false, changed: [], notes: [`${mod.name} is already ${disabled ? "disabled" : "enabled"}.`] };
483	
484	    if (disabled) {
485	      const needers = Object.entries(state.roots)
486	        .filter(([id, rr]) => id !== mod.id && rr.key !== p.key && !state.packages[rr.key]?.disabled && state.packages[rr.key]?.requires.includes(p.key))
487	        .map(([, rr]) => rr.name);
488	      if (needers.length) return { ok: false, error: `${needers.join(", ")} need${needers.length === 1 ? "s" : ""} ${mod.name} — disable ${needers.length === 1 ? "it" : "them"} first.` };
489	    } else {
490	      for (const f of p.files) {
491	        if (installer.nativeToggle) break;
492	        if (await fs.stat(f.path)) return { ok: false, error: `${f.path} already exists again (put back by hand?) — nothing was changed.` };
493	      }
494	    }
495	
496	    if (!installer.nativeToggle) {
497	      for (const f of p.files) {
498	        if (disabled) await fs.rename(f.path, disabledPath(p.key, f.path));
499	        else await fs.rename(disabledPath(p.key, f.path), f.path);
500	      }
501	      if (!disabled) await fs.remove(`${DISABLED_DIR}/${safeKey(p.key)}`);
502	      else await removeEmptyParents(fs, p.files.map((f) => f.path), layout);
503	    }
504	    p.disabled = disabled;
505	    p.updatedAt = (deps.now ?? (() => new Date()))().toISOString();
506	    if (installer.configure) {
507	      for (const e of await installer.configure(fs, layout, enabledList(state), allList(state))) {
508	        if (!isWithin(layout.base, e.path)) continue;
509	        await fs.writeFile(`${e.path}.nxeon-part`, e.data);
510	        await fs.rename(`${e.path}.nxeon-part`, e.path);
511	      }
512	    }
513	    await saveState(fs, state);
514	    return { ok: true, version: p.version, restartRequired: installer.restartRequired, changed: [`${disabled ? "disabled" : "enabled"} ${mod.name}`], notes: [] };
515	  } catch (e) {
516	    return failure(e);
517	  }
518	}
