33	async function ownedServer(serverId: string) {
34	  const user = await requireUser();
35	  if (typeof serverId !== "string" || serverId.length > 64) throw new Error("Not found");
36	  const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true } });
37	  if (!server) throw new Error("Not found");
38	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
39	  const family = familyFor(server);
40	  return { user, server, family };
