44	const hits = new Map<string, number[]>();
45	function throttled(userId: string, key: string, max: number, windowMs = 60_000): boolean {
46	  const k = `${userId}:${key}`;
47	  const now = Date.now();
48	  const arr = (hits.get(k) ?? []).filter((t) => now - t < windowMs);
49	  if (arr.length >= max) return true;
50	  arr.push(now);
51	  hits.set(k, arr);
52	  return false;
53	}
