206	/** One page of the catalogue for this server, searched and filtered in the DB. */
207	export async function searchModCatalog(
208	  serverId: string,
209	  query: CatalogQuery,
210	): Promise<{ error?: string; items?: PanelMod[]; total?: number; page?: number; pageSize?: number }> {
211	  const { server, family } = await ownedServer(serverId);
212	  if (!family) return { error: "This server doesn't support mods." };
213	  const facts = serverFacts(server, family);
214	  const q = (query.q ?? "").trim().slice(0, 80);
215	  const page = Math.max(1, Math.min(500, Math.floor(Number(query.page) || 1)));
216	
217	  const and: Prisma.GameModWhereInput[] = [{ gameFamily: family, active: true, upstreamOk: true, duplicateOfId: null }];
218	  if (q) {
219	    and.push({
220	      OR: [
221	        { name: { contains: q, mode: "insensitive" } },
222	        { slug: { contains: q.toLowerCase().replace(/\s+/g, "-") } },
223	        { description: { contains: q, mode: "insensitive" } },
224	        { authorName: { contains: q, mode: "insensitive" } },
225	      ],
226	    });
227	  }
228	  if (query.category && query.category !== "all") and.push({ category: String(query.category).slice(0, 60) });
229	  if (query.compatibleOnly) {
230	    const inst = ENGINE_INSTALLERS[family];
231	    if (inst) and.push({ source: { in: [...inst.sources] } });
232	    and.push({ OR: [{ serverSide: null }, { NOT: { serverSide: "unsupported" } }] });
233	    if (family === "minecraft") {
234	      const acc = acceptedLoaders(server.gameVariant ?? "vanilla");
235	      and.push({ category: { notIn: CLIENT_ONLY } });
236	      if (acc.length) and.push({ OR: [{ loaders: { hasSome: [...acc, "datapack"] } }, { category: "Datapacks" }] });
237	      else and.push({ OR: [{ category: "Datapacks" }, { loaders: { has: "datapack" } }] });
238	      if (facts.pinnedVersion) and.push({ OR: [{ gameVersions: { has: facts.pinnedVersion } }, { gameVersions: { isEmpty: true } }] });
239	    }
240	  }
241	  const where: Prisma.GameModWhereInput = { AND: and };
242	  const orderBy: Prisma.GameModOrderByWithRelationInput[] =
243	    query.sort === "name" ? [{ name: "asc" }]
244	    : query.sort === "updated" ? [{ upstreamUpdatedAt: { sort: "desc", nulls: "last" } }, { name: "asc" }]
245	    : query.sort === "light" ? [{ fileBytes: { sort: "asc", nulls: "last" } }, { downloads: { sort: "desc", nulls: "last" } }]
246	    : [{ featured: "desc" }, { downloads: { sort: "desc", nulls: "last" } }, { popularity: "desc" }, { name: "asc" }];
247	
248	  const [total, rows, states] = await Promise.all([
249	    db.gameMod.count({ where }),
250	    db.gameMod.findMany({ where, orderBy, skip: (page - 1) * PAGE_SIZE, take: PAGE_SIZE }),
251	    db.serverMod.findMany({ where: { serverId }, select: { modId: true, status: true, version: true, error: true } }),
252	  ]);
253	  const st = new Map(states.map((s) => [s.modId, s]));
254	  return { items: rows.map((m) => toPanel(family, m, facts, st.get(m.id))), total, page, pageSize: PAGE_SIZE };
255	}
