282	async function previewModInstallInner(serverId: string, modId: string): Promise<InstallPreview> {
283	  const { user, server, family } = await ownedServer(serverId);
284	  if (!family) return { ok: false, error: "This server doesn't support mods.", definitive: true };
285	  const mod = await db.gameMod.findUnique({ where: { id: String(modId) } });
286	  if (!mod || mod.gameFamily !== family) return { ok: false, error: "That mod isn't for this game.", definitive: true };
287	  const inst = engineInstallerFor(family, mod.source);
288	  if (!inst) {
289	    return {
290	      ok: true,
291	      packages: [{ name: mod.name, version: "latest", root: true, size: mod.fileBytes }],
292	      notes: ["Dependencies for this game are handled by the game itself or checked on the server during the install."],
293	      restartRequired: true,
294	      exact: false,
295	    };
296	  }
297	  if (throttled(user.id, "mod-preview", 30)) return { ok: false, error: "Too many previews in a minute — try again shortly.", definitive: false };
298	  const facts = serverFacts(server, family);
299	  // Without the guest we only know the pinned version. A version-sensitive
300	  // game that isn't pinned gets its exact build (and dependencies) chosen on
301	  // the server at install time — said so, rather than guessed here.
302	  if (inst.versionSensitive && !facts.pinnedVersion) {
303	    return { ok: true, packages: [{ name: mod.name, version: "best match for your server", root: true, size: mod.fileBytes }], notes: ["Dependencies are resolved against your server's real version during the install."], restartRequired: inst.restartRequired, exact: false };
304	  }
305	  const r = await previewResolve(inst, catalogFacts(mod), facts, safeFetch, PREVIEW_LAYOUT(facts.pinnedVersion));
306	  if (!r.ok) return r;
307	  return { ...r, exact: !!facts.pinnedVersion };
308	}
