310	const CLIENT_ACK_ERROR = "Players need this mod too. Confirm that you will tell them before installing.";
311	
312	async function act(serverId: string, modId: string, op: ModOp, opts?: { ackClient?: boolean }): Promise<{ ok?: true; error?: string; jobId?: string }> {
313	  const { user, server, family } = await ownedServer(serverId);
314	  if (!family) return { error: "This server doesn't support mods." };
315	  if (server.status !== "RUNNING") return { error: "Start the server's VM first — mods are installed onto the running server." };
316	  const mod = await db.gameMod.findUnique({ where: { id: String(modId) } });
317	  if (!mod) return { error: "That mod is unavailable." };
318	  if (mod.gameFamily !== family) return { error: "That mod isn't for this game." };
319	  if (op === "install") {
320	    if (!mod.active || !mod.upstreamOk) return { error: "That mod is no longer available upstream." };
321	    const sup = installSupport(family, mod.source);
322	    if (!sup.ok) return { error: sup.message };
323	    const c = compatFor(family, mod, serverFacts(server, family));
324	    if (c.verdict === "unsupported") return { error: c.detail };
325	    // A mod every player must also install is only installed once the owner has
326	    // seen the warning (the install dialog sends ackClient). Direct callers that
327	    // skip the dialog get the same message instead of a silent lock-out.
328	    if (clientWarningFor(mod, server.gameVariant ?? null).required === true && !opts?.ackClient) return { error: CLIENT_ACK_ERROR };
329	  }
330	  if ((op === "update" || op === "disable" || op === "enable") && !engineInstallerFor(family, mod.source)) {
331	    return { error: "That action isn't available for this game yet." };
332	  }
333	  const r = await enqueueModOp(serverId, mod.id, op, { userId: user.id, slug: mod.slug });
334	  if (!r.ok) return { error: r.error };
335	  revalidatePath(`/dashboard/servers/${serverId}`);
336	  return { ok: true, jobId: r.jobId };
337	}
