356	export async function checkModUpdates(serverId: string): Promise<{ error?: string; updates?: Record<string, string | null> }> {
357	  const { user, server, family } = await ownedServer(serverId);
358	  if (!family) return { error: "This server doesn't support mods." };
359	  if (throttled(user.id, "mod-updates", 4)) return { error: "Checked very recently — try again in a minute." };
360	  const rows = await db.serverMod.findMany({ where: { serverId, status: { in: ["INSTALLED", "DISABLED"] } }, include: { mod: true }, take: 15 });
361	  const facts = serverFacts(server, family);
362	  const work = rows.filter((r) => engineInstallerFor(family, r.mod.source));
363	  const out: Record<string, string | null> = {};
364	  let i = 0;
365	  await Promise.all(
366	    Array.from({ length: 3 }, async () => {
367	      while (i < work.length) {
368	        const r = work[i++];
369	        const inst = engineInstallerFor(family, r.mod.source)!;
370	        const p = await previewResolve(inst, catalogFacts(r.mod), facts, safeFetch, PREVIEW_LAYOUT(facts.pinnedVersion)).catch(() => null);
371	        const root = p && p.ok ? p.packages.find((x) => x.root) : null;
372	        out[r.modId] = root ? root.version : null;
373	      }
374	    }),
375	  );
376	  return { updates: out };
377	}
