76	export async function gameModSync(job: Job): Promise<void> {
77	  const serverId = job.serverId;
78	  if (!serverId) throw new Error("game mod sync: job has no serverId");
79	
80	  const server = await db.server.findUnique({
81	    where: { id: serverId },
82	    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
83	  });
84	  if (!server) throw new Error(`Server ${serverId} not found`);
