102	  const engineRows = pending.filter((sm) => engineInstallerFor(sm.mod.gameFamily, sm.mod.source));
103	  const legacyRows = pending.filter((sm) => !engineInstallerFor(sm.mod.gameFamily, sm.mod.source));
104	  const step = async (text: string, pct: number) => {
105	    await db.job.update({ where: { id: job.id }, data: { step: text.slice(0, 180), progress: Math.max(0, Math.min(99, pct)) } }).catch(() => {});
106	  };
107	
108	  try {
109	    for (const [n, sm] of engineRows.entries()) {
110	      const installer = engineInstallerFor(sm.mod.gameFamily, sm.mod.source)!;
111	      const op = sm.status;
112	      let result: OpResult;
113	      if (!SANDBOX && !REAL_ENABLED) {
114	        result = { ok: false, error: "Mod installation is being enabled for this game — your change was not applied yet. Our team has been notified." };
115	      } else {
116	        try {
117	          if (!guest) {
