131	            progress: (text, pct) => step(`${sm.mod.name}: ${text}`, Math.round(((n + pct / 100) / engineRows.length) * 100)),
132	          };
133	          const facts = serverFacts(server, sm.mod.gameFamily);
134	          const cf = catalogFacts(sm.mod);
135	          result =
136	            op === "REMOVING" ? await engineUninstall(installer, cf, facts, deps)
137	            : op === "DISABLING" ? await engineSetDisabled(installer, cf, facts, deps, true)
138	            : op === "ENABLING" ? await engineSetDisabled(installer, cf, facts, deps, false)
139	            : await installOrUpdate(installer, cf, facts, deps, op === "UPDATING" ? "update" : "install");
140	        } catch (e) {
