142	        }
143	      }
144	
145	      const label = `${op.toLowerCase()} ${sm.mod.slug}`;
146	      if (result.ok) {
147	        restartRequired ||= result.restartRequired;
148	        changed.push(...result.changed);
149	        if (op === "REMOVING") {
150	          await db.serverMod.delete({ where: { id: sm.id } });
