/**
 * Mod health check after a game restart or update (growth batch G5, prd-004).
 *
 * Why: customers installed mods that "disappeared" after a Steam update until a
 * manual restart (ticket 11, 2026-09-20), and a game update can leave a mod that
 * no longer matches the new game build. After the game has restarted, the log
 * says which mods actually loaded. This module reads that log. It is PURE (log
 * text in, verdicts out); worker/mod-health.ts does the SSH and the actions.
 *
 * Honesty rules:
 *  - A mod is only "loaded" when its load line is in the log since the game's
 *    last start. "Not seen" is not "broken": the log may be short or the mod may
 *    be silent, so a not-seen mod only ever triggers a notice (and at most one
 *    restart while the server is empty), never a pause.
 *  - A mod is only "error" on positive evidence: an error line that names it.
 *    Only error evidence may pause a mod, and only when the platform setting
 *    allows it.
 *  - Games whose log has no reliable per-mod line are "unknown" and say so.
 *
 * Marker formats (what each framework writes when it loads a plugin):
 *   BepInEx (Valheim)  `[Info   :   BepInEx] Loading [Plugin Name 1.2.3]`
 *   Oxide / Carbon     `Loaded plugin PluginName v1.2.3 by Author`
 *   Paper / Spigot     `[Server thread/INFO]: [PluginName] Enabling PluginName v1.2.3`
 *   TShock (Terraria)  `Plugin PluginName v1.2.3 (by Author) initiated.`
 * Written from each project's own log output as documented; NOT yet confirmed
 * against a live customer server. docs/DOCUMENTATION.md, "Growth batch G5".
 */

export type HealthMod = {
  /** Display name from the catalogue. */
  name: string;
  /** Source id (Thunderstore "Author-Name", uMod key, Modrinth slug...). */
  key: string;
  /** File the installer wrote, if known. */
  fileName?: string | null;
};

export type ModHealthStatus = "loaded" | "error" | "not-seen" | "unknown";

export type ModVerdict = { mod: HealthMod; status: ModHealthStatus; evidence: string | null };

export type HealthReport = {
  /** Does this game/loader have a per-mod log line we can read at all? */
  supported: boolean;
  /** The framework itself (BepInEx, Oxide...) is visibly running. null = not applicable. */
  frameworkUp: boolean | null;
  verdicts: ModVerdict[];
  /** Overall: ok = every mod loaded, warn = something to look at, unknown = cannot tell. */
  overall: "ok" | "warn" | "unknown";
  /** Mods with positive error evidence: the only ones that may be paused. */
  errored: ModVerdict[];
  /** Mods not seen while the framework is clearly up: one restart may help. */
  missing: ModVerdict[];
};

const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, "");

/** Name forms a log line might use for this mod. */
export function nameForms(m: HealthMod): string[] {
  const forms = new Set<string>();
  const add = (s: string | null | undefined) => {
    const n = norm(s ?? "");
    if (n.length >= 4) forms.add(n);
  };
  add(m.name);
  add((m.key.includes("-") ? m.key.split("-").slice(1).join("-") : m.key));
  add(m.key);
  if (m.fileName) add(m.fileName.replace(/\.(dll|jar|cs|zip)$/i, ""));
  return [...forms];
}

const nameMatches = (forms: string[], logged: string) => {
  const l = norm(logged);
  return !!l && forms.some((f) => l === f || (f.length >= 6 && l.includes(f)) || (l.length >= 6 && f.includes(l)));
};

function bepinex(mods: HealthMod[], log: string): HealthReport {
  const loading = [...log.matchAll(/\[(?:Info|Message)\s*:\s*BepInEx\]\s*Loading \[(.+?) [0-9][^\]]*\]/g)].map((m) => m[1]);
  const frameworkUp = /BepInEx/.test(log) && (loading.length > 0 || /BepInEx \d|Chainloader|Loaded \d+ plugins?/i.test(log));
  const errorLines = log.split(/\r?\n/).filter((l) => /\[(?:Error|Fatal)\s*:/.test(l) && /BepInEx|Harmony|Exception/.test(l));
  const verdicts = mods.map((mod): ModVerdict => {
    const forms = nameForms(mod);
    const err = errorLines.find((l) => forms.some((f) => norm(l).includes(f)));
    if (err) return { mod, status: "error", evidence: err.trim().slice(0, 240) };
    const hit = loading.find((n) => nameMatches(forms, n));
    if (hit) return { mod, status: "loaded", evidence: `BepInEx loaded "${hit}"` };
    return { mod, status: frameworkUp ? "not-seen" : "unknown", evidence: null };
  });
  return finish(true, frameworkUp, verdicts);
}

function oxide(mods: HealthMod[], log: string): HealthReport {
  const loaded = [...log.matchAll(/Loaded plugin (.+?) v[0-9][^\s]*(?: by .+)?/g)].map((m) => m[1]);
  const frameworkUp = /Oxide|Carbon/i.test(log) && (loaded.length > 0 || /\[(?:Oxide|Carbon)\]|Loading Oxide|Loaded Oxide|Carbon (?:v|\d)/i.test(log));
  const errs = log.split(/\r?\n/).filter((l) => /Error while compiling|Failed to compile|Failed to load plugin|Failed to call hook/i.test(l));
  const verdicts = mods.map((mod): ModVerdict => {
    const forms = nameForms(mod);
    const err = errs.find((l) => forms.some((f) => norm(l).includes(f)));
    if (err) return { mod, status: "error", evidence: err.trim().slice(0, 240) };
    const hit = loaded.find((n) => nameMatches(forms, n));
    if (hit) return { mod, status: "loaded", evidence: `Loaded plugin ${hit}` };
    return { mod, status: frameworkUp ? "not-seen" : "unknown", evidence: null };
  });
  return finish(true, frameworkUp, verdicts);
}

function paper(mods: HealthMod[], log: string): HealthReport {
  const enabling = [...log.matchAll(/\[([^\]\n]+)\]\s*Enabling \1 v?[0-9]/g)].map((m) => m[1]);
  const frameworkUp = /Done \(|Preparing level|Loading libraries|Starting minecraft server/i.test(log);
  const errs = log.split(/\r?\n/).filter((l) => /Could not load '|Error occurred while enabling|Disabling [A-Za-z0-9_.-]+ v|Invalid plugin\.yml|UnsupportedClassVersionError/i.test(l));
  const verdicts = mods.map((mod): ModVerdict => {
    const forms = nameForms(mod);
    const err = errs.find((l) => forms.some((f) => norm(l).includes(f)));
    if (err) return { mod, status: "error", evidence: err.trim().slice(0, 240) };
    const hit = enabling.find((n) => nameMatches(forms, n));
    if (hit) return { mod, status: "loaded", evidence: `[${hit}] Enabling` };
    return { mod, status: frameworkUp ? "not-seen" : "unknown", evidence: null };
  });
  return finish(true, frameworkUp, verdicts);
}

}

function tshock(mods: HealthMod[], log: string): HealthReport {
  const init = [...log.matchAll(/Plugin (.+?) v[0-9][^\s]* \(by .+?\) initiated/g)].map((m) => m[1]);
  const frameworkUp = /TShock/i.test(log);
  const errs = log.split(/\r?\n/).filter((l) => /Plugin .+ failed to load|Failed to load assembly|has failed to load/i.test(l));
  const verdicts = mods.map((mod): ModVerdict => {
    const forms = nameForms(mod);
    const err = errs.find((l) => forms.some((f) => norm(l).includes(f)));
    if (err) return { mod, status: "error", evidence: err.trim().slice(0, 240) };
    const hit = init.find((n) => nameMatches(forms, n));
    if (hit) return { mod, status: "loaded", evidence: `Plugin ${hit} initiated` };
    return { mod, status: frameworkUp ? "not-seen" : "unknown", evidence: null };
  });
  return finish(true, frameworkUp, verdicts);
}

function finish(supported: boolean, frameworkUp: boolean | null, verdicts: ModVerdict[]): HealthReport {
  const errored = verdicts.filter((v) => v.status === "error");
  const missing = verdicts.filter((v) => v.status === "not-seen");
  const unknown = verdicts.filter((v) => v.status === "unknown");
  const overall: HealthReport["overall"] = errored.length || missing.length ? "warn" : unknown.length === verdicts.length && verdicts.length > 0 ? "unknown" : "ok";
  return { supported, frameworkUp, verdicts, overall, errored, missing };
}

/** Families + server types whose log we can read per mod. */
export function healthSupported(family: string, variant: string | null): boolean {
  const v = (variant ?? "").toLowerCase();
  if (family === "valheim") return v === "bepinex";
  if (family === "rust") return v === "oxide" || v === "carbon";
  if (family === "terraria") return true;
  if (family === "minecraft") return ["paper", "purpur", "spigot", "bukkit", "folia"].includes(v);
  return false;
}

export function judgeModHealth(input: { family: string; variant: string | null; mods: HealthMod[]; log: string }): HealthReport {
  const { family, mods, log } = input;
  const v = (input.variant ?? "").toLowerCase();
  if (!healthSupported(family, input.variant)) {
    return { supported: false, frameworkUp: null, verdicts: mods.map((mod) => ({ mod, status: "unknown", evidence: null })), overall: "unknown", errored: [], missing: [] };
  }
  if (family === "valheim") return bepinex(mods, log);
  if (family === "rust") return oxide(mods, log);
  if (family === "terraria") return tshock(mods, log);
  if (family === "minecraft" && v) return paper(mods, log);
  return { supported: false, frameworkUp: null, verdicts: mods.map((mod) => ({ mod, status: "unknown", evidence: null })), overall: "unknown", errored: [], missing: [] };
}

/** What the worker may do about a report. Pure so it is tested. */
export type HealthAction =
  | { kind: "none"; why: string }
  | { kind: "notify"; why: string }
  | { kind: "restart"; why: string }
  | { kind: "pause"; mods: ModVerdict[]; why: string };

export function decideHealthAction(input: {
  report: HealthReport;
  /** null = unknown. */
  playersOnline: number | null;
  /** The restart already happened once for this start; never loop. */
  alreadyRestartedForThisStart: boolean;
  autoPause: boolean;
  autoRestart: boolean;
}): HealthAction {
  const { report: r } = input;
  if (!r.supported) return { kind: "none", why: "This game has no per-mod load line we can read." };
  if (r.overall === "ok") return { kind: "none", why: "Every installed mod loaded." };
  if (r.overall === "unknown") return { kind: "none", why: "The log didn't show whether the mods loaded (framework not seen yet)." };
  if (r.errored.length && input.autoPause) return { kind: "pause", mods: r.errored, why: `${r.errored.map((v) => v.mod.name).join(", ")} failed to load` };
  if (r.missing.length && !r.errored.length && input.autoRestart && !input.alreadyRestartedForThisStart && input.playersOnline === 0) {
    return { kind: "restart", why: `${r.missing.map((v) => v.mod.name).join(", ")} not seen in the log; the server is empty, so one restart is safe` };
  }
  return { kind: "notify", why: r.errored.length ? "A mod failed to load." : "A mod did not show up in the log." };
}

/** One-paragraph customer text. */
export function healthSummary(r: HealthReport, action: HealthAction): string {
  if (!r.supported) return "This game's log doesn't list loaded mods, so they were not checked.";
  const loaded = r.verdicts.filter((v) => v.status === "loaded").length;
  const bits = [`${loaded} of ${r.verdicts.length} mod${r.verdicts.length === 1 ? "" : "s"} confirmed loaded.`];
  if (r.errored.length) bits.push(`Failed to load: ${r.errored.map((v) => v.mod.name).join(", ")}.`);
  if (r.missing.length) bits.push(`Not seen in the log: ${r.missing.map((v) => v.mod.name).join(", ")}.`);
  if (action.kind === "restart") bits.push("We restarted the server once (nobody was online) to load them.");
  if (action.kind === "pause") bits.push("We paused them so players don't hit version-mismatch errors. Re-enable them from the Mods tab once an update is out.");
  if (action.kind === "notify" && r.errored.length + r.missing.length) bits.push("Nothing was changed. Check the Mods tab, or restart when nobody is playing.");
  return bits.join(" ");
}
/**
 * Mod health after a game restart / update (prd-004; lib/mod-health.ts holds the
 * logic). Registered on the SweepRunner as "mod-health" (worker/index.ts).
 *
 * INERT unless ENABLE_MOD_HEALTH=1. Reading a log is harmless, but the actions
 * it can take are not, so each has its own switch and its own guards:
 *
 *   ENABLE_MOD_HEALTH=1        check + record + notify (read-only on the server)
 *   MOD_HEALTH_AUTORESTART=0   turn the one safe restart off (default on, within the flag)
 *   MOD_HEALTH_AUTOPAUSE=1     pause a mod with POSITIVE error evidence (needs ENABLE_REAL_GAMEMODS=1)
 *   MOD_HEALTH=off             kill switch
 *
 * When it checks: a server whose game process started (GameRuntime.startedAt,
 * the fleet probe) more than 4 minutes ago and whose start has not been checked
 * yet. That covers a Steam/game update restart, a crash restart, a customer
 * restart and a mod install, with no extra bookkeeping on the update path.
 *
 * Guards (restart): the server must have ZERO players counted (null = unknown =
 * no restart), at most one auto-restart per server per 6 hours, never while any
 * job is queued/running, and never for a mod that merely wasn't seen AND has an
 * error elsewhere (that needs a human). A server with players only gets a notice.
 */
import type { Job } from "@prisma/client";
import { db } from "../lib/db";
import { familyFor } from "../lib/game-config";
import { withServerSsh, exec as sshExec } from "../lib/ssh-exec";
import { healthSupported, judgeModHealth, decideHealthAction, healthSummary, type HealthMod } from "../lib/mod-health";
import { dockerContainerNameFrom } from "./game-variant";
import { enqueueModOp } from "../lib/mods/queue";
import { playersOnline } from "./mod-autoupdate";

const SETTLE_MS = 4 * 60_000;
const RESTART_COOLDOWN_MS = 6 * 3600_000;
const PER_SWEEP = 5;
const CONTAINER_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,62}$/;

export const modHealthConfig = (env: NodeJS.ProcessEnv = process.env) => ({
  enabled: env.ENABLE_MOD_HEALTH === "1" && env.MOD_HEALTH !== "off",
  autoRestart: env.MOD_HEALTH_AUTORESTART !== "0",
  autoPause: env.MOD_HEALTH_AUTOPAUSE === "1" && env.ENABLE_REAL_GAMEMODS === "1",
});

let running = false;

export async function modHealthSweep(): Promise<{ checked: number }> {
  const cfg = modHealthConfig();
  if (!cfg.enabled || running) return { checked: 0 };
  running = true;
  let checked = 0;
  try {
    const servers = await db.server.findMany({
      where: { status: "RUNNING", mods: { some: { status: "INSTALLED" } }, gameRuntime: { state: "online", startedAt: { not: null, lt: new Date(Date.now() - SETTLE_MS) } } },
      include: {
        osTemplate: true,
        gamePlan: true,
        node: true,
        dedicatedIp: true,
        gameRuntime: { select: { startedAt: true, intent: true } },
        mods: { where: { status: "INSTALLED" }, include: { mod: { select: { name: true, sourceId: true } } } },
      },
      take: 400,
    });
    for (const s of servers) {
      if (checked >= PER_SWEEP) break;
      const family = familyFor(s);
      if (!family || !healthSupported(family, s.gameVariant ?? null)) continue;
      if (s.gameRuntime?.intent === "stopped") continue;
      const startedAt = s.gameRuntime!.startedAt!;
      const last = await db.modUpdateRun.findFirst({ where: { serverId: s.id, trigger: "health" }, orderBy: { startedAt: "desc" }, select: { plan: true } });
      if (((last?.plan ?? {}) as { startedAt?: string }).startedAt === startedAt.toISOString()) continue;
      if ((await db.job.count({ where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } } })) > 0) continue;
      checked++;
      try {
        await checkOne(s as unknown as Loaded, family, startedAt, cfg);
      } catch (e) {
        console.error(`[mod-health] ${s.hostname}:`, (e as Error).message);
        // Record the attempt so a server we cannot read is not retried every sweep.
        await db.modUpdateRun.create({ data: { serverId: s.id, trigger: "health", status: "NOOP", summary: "Couldn't read the server's log to check its mods.", plan: { startedAt: startedAt.toISOString() }, finishedAt: new Date() } }).catch(() => {});
      }
    }
  } finally {
    running = false;
  }
  return { checked };
}

type Loaded = {
  id: string; userId: string; hostname: string; gameVariant: string | null;
  osTemplate: { name: string; setupScript: string | null };
  mods: { mod: { name: string; sourceId: string | null }; fileName: string | null }[];
};

async function readLog(server: Loaded, since: Date): Promise<string> {
  const container = dockerContainerNameFrom(server.osTemplate.setupScript ?? "");
  if (!container || !CONTAINER_RE.test(container)) throw new Error("no container name");
  const cmd = `docker logs --since ${since.toISOString()} ${container} 2>&1 | tail -n 4000`;
  const r = await withServerSsh(server as never, (conn) => sshExec(conn, cmd, 30_000));
  return r.stdout;
}

async function checkOne(server: Loaded, family: string, startedAt: Date, cfg: ReturnType<typeof modHealthConfig>) {
  const log = await readLog(server, startedAt);
  const mods: HealthMod[] = server.mods.map((m) => ({ name: m.mod.name, key: m.mod.sourceId ?? m.mod.name, fileName: m.fileName }));
  const report = judgeModHealth({ family, variant: server.gameVariant, mods, log });
  const players = await playersOnline(server.id, family);
  const recentRestart = await db.modUpdateRun.findFirst({
    where: { serverId: server.id, trigger: "health", status: "HEALTH_RESTARTED", startedAt: { gt: new Date(Date.now() - RESTART_COOLDOWN_MS) } },
    select: { id: true },
  });
  const action = decideHealthAction({ report, playersOnline: players, alreadyRestartedForThisStart: !!recentRestart, autoPause: cfg.autoPause, autoRestart: cfg.autoRestart });

  let status = report.overall === "ok" ? "HEALTH_OK" : report.overall === "unknown" ? "NOOP" : "HEALTH_WARN";
  const href = `/dashboard/servers/${server.id}?tab=mods`;
  if (action.kind === "restart") {
    const busy = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
    if (!busy) {
      await db.job.create({ data: { type: "GAME_POWER", serverId: server.id, payload: { action: "restart", announce: false, source: "auto-restart" } } });
      status = "HEALTH_RESTARTED";
    }
  } else if (action.kind === "pause") {
    const first = action.mods[0];
    const row = await db.serverMod.findFirst({ where: { serverId: server.id, status: "INSTALLED", mod: { sourceId: first.mod.key } }, select: { modId: true } });
    if (row) {
      const r = await enqueueModOp(server.id, row.modId, "disable", { userId: server.userId, slug: first.mod.key });
      if (r.ok) status = "HEALTH_PAUSED";
    }
  }
  const summary = healthSummary(report, action);
  await db.modUpdateRun.create({
    data: {
      serverId: server.id, trigger: "health", status, summary,
      plan: { startedAt: startedAt.toISOString(), verdicts: report.verdicts.map((v) => ({ name: v.mod.name, status: v.status, evidence: v.evidence })), action: action.kind } as never,
      finishedAt: new Date(),
    },
  });
  // Tell the customer only when something needs them (never "all good" noise).
  if (report.overall === "warn") {
    await db.notification
      .create({ data: { userId: server.userId, title: `${server.hostname}: a mod needs a look`, body: summary, href } })
      .catch(() => {});
  }
}

