/**
 * DB rows → the plain facts the installers work from. Shared by the worker
 * (worker/game-mods.ts) and the portal actions (lib/actions-mods.ts) so both
 * judge a server the same way.
 */
import type { CatalogFacts, ServerFacts } from "./types";

/** ServerMod.status values that ask the worker to do something. */
export const ENGINE_PENDING_STATUSES = ["INSTALLING", "REMOVING", "UPDATING", "DISABLING", "ENABLING"] as const;
/** Every ServerMod.status the portal can show. DISABLED is a resting state. */
export const SERVER_MOD_STATUSES = [...ENGINE_PENDING_STATUSES, "INSTALLED", "DISABLED", "FAILED"] as const;

type ModRowLike = {
  id: string;
  gameFamily: string;
  slug: string;
  name: string;
  source: string;
  sourceId: string | null;
  url: string | null;
  category: string;
  appliesToVariant: string | null;
  loaders?: string[] | null;
  gameVersions?: string[] | null;
  serverSide?: string | null;
};

export function catalogFacts(m: ModRowLike): CatalogFacts {
  return {
    id: m.id,
    gameFamily: m.gameFamily,
    slug: m.slug,
    name: m.name,
    source: m.source,
    sourceId: m.sourceId,
    url: m.url,
    category: m.category,
    appliesToVariant: m.appliesToVariant,
    loaders: m.loaders ?? [],
    gameVersions: m.gameVersions ?? [],
    serverSide: m.serverSide ?? null,
  };
}

/** The pinned VERSION from the server's game config, when it names a real version. */
export function pinnedVersion(config: unknown): string | null {
  const cfg = (config ?? null) as Record<string, unknown> | null;
  const raw = cfg && typeof cfg.VERSION === "string" ? cfg.VERSION.trim() : "";
  return raw && !/^(latest|snapshot|stable|experimental)$/i.test(raw) && /^[0-9A-Za-z.\-+_]{1,40}$/.test(raw) ? raw : null;
}

export function serverFacts(s: { id: string; gameVariant: string | null; gameConfig?: unknown; osTemplate?: { family: string } | null }, family?: string): ServerFacts {
  return {
    id: s.id,
    family: family ?? s.osTemplate?.family ?? "",
    variant: s.gameVariant ?? null,
    pinnedVersion: pinnedVersion(s.gameConfig),
    config: (s.gameConfig ?? null) as Record<string, unknown> | null,
  };
}

