/**
 * Enable/disable WITHOUT uninstalling — what each game really allows.
 *
 * This is the vetting (/root/agent-notes/mods-rework/VETTING.md, summarised in
 * docs/DOCUMENTATION.md) turned into code, so the portal, the server actions
 * and the worker all ask the same question and get the same answer. It is
 * PURE: no DB, no network, no guest.
 *
 * Three verdicts per family:
 *   SAFE              — taking the mod out of the load path and putting it back
 *                       loses nothing; the mod's own data/config stays on disk.
 *   SAFE_WITH_WARNING — the toggle itself is mechanically clean and reversible,
 *                       BUT a mod that adds content (blocks, items, buildings,
 *                       creatures, prototypes) is deleted from the world the
 *                       first time the game loads and saves without it.
 *                       Re-enabling does NOT bring that content back. Those
 *                       toggles need the owner to acknowledge it, and the panel
 *                       offers a world backup first.
 *   NOT_SUPPORTED     — either nobody has built a toggle for this family on
 *                       Nxeon (no state file to move files with), or it can't
 *                       be done honestly. The panel draws no toggle at all.
 *
 * A toggle is ONLY offered for families whose installs go through the shared
 * engine (lib/mods/engine.ts), because that is the only path that records
 * exactly which files Nxeon placed (/root/.nxeon-mods/state.json) — moving
 * files we can't name precisely is how a "disable" deletes the wrong thing.
 */

export type ToggleSafety = "SAFE" | "SAFE_WITH_WARNING" | "NOT_SUPPORTED";
/** move-aside: files move to /root/.nxeon-mods/disabled/<key>/…; native-flag: the game's own mod list says enabled=false. */
export type ToggleStrategy = "move-aside" | "native-flag" | "none";
/** hot: the framework unloads/loads on its own; restart: next game start. */
export type ToggleRestart = "hot" | "restart" | "none";

export type FamilyTogglePolicy = {
  family: string;
  safety: ToggleSafety;
  strategy: ToggleStrategy;
  restart: ToggleRestart;
  /** One plain sentence for the customer: how a disable works on this game. */
  how: string;
  /** Why NOT_SUPPORTED (customer-facing), or the general caveat otherwise. */
  note: string | null;
};

export type ToggleModFacts = {
  name: string;
  /** GameMod.category (Nxeon's coarse bucket). */
  category: string;
  /** GameMod.categories (provider categories, e.g. Modrinth "worldgen"). */
  categories?: string[] | null;
  tags?: string[] | null;
  loaders?: string[] | null;
};

export type ToggleDecision =
  | { allowed: false; safety: "NOT_SUPPORTED"; reason: string }
  | {
      allowed: true;
      safety: "SAFE" | "SAFE_WITH_WARNING";
      strategy: Exclude<ToggleStrategy, "none">;
      restart: ToggleRestart;
      /** This specific mod may delete world content when disabled. */
      contentRisk: boolean;
      /** Customer-facing warning shown before a disable (null = none needed). */
      warning: string | null;
      /** The server refuses the disable unless the owner acknowledged the warning. */
      needsAck: boolean;
    };

const PLUGIN_VARIANTS = new Set(["paper", "purpur", "spigot", "bukkit", "folia", "pufferfish", "leaf"]);
const MOD_VARIANTS = new Set(["fabric", "quilt", "forge", "neoforge"]);

/** Families with an engine installer — the only ones a toggle can exist for. Kept in step with lib/mods/installers/index.ts by a test. */
export const TOGGLE_ENGINE_FAMILIES = ["minecraft", "valheim", "rust", "cs2", "factorio", "corekeeper"] as const;

const NOT_BUILT = "Disabling without uninstalling isn't available for this game on Nxeon yet — remove the mod instead, and reinstall it from the store later.";

/** Customer-facing reason per non-engine family (from the vetting). */
const NOT_SUPPORTED_REASON: Record<string, string> = {
  terraria: NOT_BUILT,
  ark: "ARK downloads its mods itself from the mod list, and a mod taken off that list deletes its structures, dinos and items from the save. Remove it instead if you're sure.",
  projectzomboid: NOT_BUILT,
  dst: NOT_BUILT,
  unturned: NOT_BUILT,
  squad: NOT_BUILT,
  soulmask: NOT_BUILT,
  tf2: NOT_BUILT,
  l4d2: NOT_BUILT,
  kf2: NOT_BUILT,
  gmod: NOT_BUILT,
  necesse: NOT_BUILT,
  empyrion: "An Empyrion scenario is what your save is built on — it can't be switched off while the world uses it.",
  vintagestory: NOT_BUILT,
  satisfactory: NOT_BUILT,
  armareforger: NOT_BUILT,
};

export function familyTogglePolicy(family: string, variant: string | null): FamilyTogglePolicy {
  const v = (variant ?? "").toLowerCase();
  switch (family) {
    case "minecraft":
      if (PLUGIN_VARIANTS.has(v)) {
        return {
          family, safety: "SAFE", strategy: "move-aside", restart: "restart",
