  engine: boolean;
}): ToggleDecision {
  const pol = familyTogglePolicy(input.family, input.variant);
  if (pol.safety === "NOT_SUPPORTED" || pol.strategy === "none") return { allowed: false, safety: "NOT_SUPPORTED", reason: pol.note ?? NOT_BUILT };
