/* ── dependency awareness (pure; graph comes from the guest state) ──────── */

/** modId → the other installed root modIds it needs (direct or through shared packages). */
export type DepGraph = Record<string, string[]>;

export type PlannedToggle = { modId: string; op: "disable" | "enable" };

/**
 * Check a batch of toggles against the dependency graph and the current
 * enabled set. Returns the problems (customer-facing) and a safe ORDER to
 * apply them in: disables of dependents before the things they need, enables
 * of needed things before their dependents.
 */
export function planToggles(
  plan: PlannedToggle[],
  graph: DepGraph,
  enabled: Set<string>,
  names: Record<string, string>,
): { ok: boolean; problems: string[]; order: PlannedToggle[] } {
  const after = new Set(enabled);
  for (const p of plan) (p.op === "disable" ? after.delete(p.modId) : after.add(p.modId));
  const nm = (id: string) => names[id] ?? "another mod";
  const problems: string[] = [];
  for (const p of plan) {
    if (p.op === "disable") {
      const needers = Object.entries(graph).filter(([id, req]) => id !== p.modId && after.has(id) && req.includes(p.modId)).map(([id]) => nm(id));
      if (needers.length) problems.push(`${needers.join(", ")} need${needers.length === 1 ? "s" : ""} ${nm(p.modId)} — disable ${needers.length === 1 ? "it" : "them"} too, or keep ${nm(p.modId)} on.`);
    } else {
      const missing = (graph[p.modId] ?? []).filter((d) => d !== p.modId && !after.has(d) && d in names).map(nm);
      if (missing.length) problems.push(`${nm(p.modId)} needs ${missing.join(", ")} — enable ${missing.length === 1 ? "it" : "them"} too.`);
    }
  }
  // Order: all disables first (dependents before dependencies), then enables (dependencies first).
  const depth = (id: string, seen = new Set<string>()): number => {
    if (seen.has(id)) return 0;
    seen.add(id);
    const req = graph[id] ?? [];
    return req.length ? 1 + Math.max(...req.map((r) => depth(r, seen))) : 0;
  };
  const dis = plan.filter((p) => p.op === "disable").sort((a, b) => depth(b.modId) - depth(a.modId));
  const en = plan.filter((p) => p.op === "enable").sort((a, b) => depth(a.modId) - depth(b.modId));
  return { ok: problems.length === 0, problems, order: [...dis, ...en] };
}

