        if (!fromSt) return { ok: false, error: `${from} is missing (removed by hand?), so ${mod.name} can't be ${verb} — nothing was changed. Reinstall it instead.` };
        if (toSt) return { ok: false, error: `${to} already exists${disabled ? "" : " again (put back by hand?)"} — nothing was changed.` };
        moves.push({ from, to, rec: f });
      }
    }

