import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, rmSync, existsSync, writeFileSync, mkdirSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";

import { familyTogglePolicy, toggleDecision, contentRisk, planToggles, isModpack, TOGGLE_ENGINE_FAMILIES } from "../lib/mods/toggle-policy.ts";
import { orderPendingByPlan, validateBatch, batchOpsFromPayload, OP_FROM } from "../lib/mods/batch.ts";
import { setDisabled, uninstall, dependencyGraph, loadState, STATE_PATH, type GuestState } from "../lib/mods/engine.ts";
import { LocalGuestFs } from "../lib/mods/guest-fs.ts";
import { ENGINE_INSTALLERS } from "../lib/mods/installers/index.ts";
import { valheimSyncedCopy, VALHEIM_SYNCED_PLUGINS } from "../lib/mods/installers/valheim.ts";
import type { CatalogFacts, FamilyInstaller, ServerFacts } from "../lib/mods/types.ts";

/* ── policy (the vetting as code) ─────────────────────────────────────────── */

test("toggle policy: every engine family has a supported policy, and only engine families do", () => {
  assert.deepEqual([...TOGGLE_ENGINE_FAMILIES].sort(), Object.keys(ENGINE_INSTALLERS).sort());
  for (const f of TOGGLE_ENGINE_FAMILIES) assert.notEqual(familyTogglePolicy(f, f === "minecraft" ? "paper" : f === "valheim" ? "bepinex" : null).safety, "NOT_SUPPORTED", f);
  for (const f of ["terraria", "ark", "projectzomboid", "gmod", "palworld", "sdtd", "vrising", "enshrouded", "satisfactory", "empyrion"]) {
    const p = familyTogglePolicy(f, null);
    assert.equal(p.safety, "NOT_SUPPORTED", f);
    assert.equal(p.strategy, "none");
    assert.ok(p.note && p.note.length > 10);
  }
});

test("toggle policy: per-family strategy and restart", () => {
  assert.deepEqual(pick(familyTogglePolicy("minecraft", "paper")), ["SAFE", "move-aside", "restart"]);
  assert.deepEqual(pick(familyTogglePolicy("minecraft", "Purpur")), ["SAFE", "move-aside", "restart"]);
  assert.deepEqual(pick(familyTogglePolicy("minecraft", "fabric")), ["SAFE_WITH_WARNING", "move-aside", "restart"]);
  assert.deepEqual(pick(familyTogglePolicy("minecraft", "neoforge")), ["SAFE_WITH_WARNING", "move-aside", "restart"]);
  assert.deepEqual(pick(familyTogglePolicy("rust", "oxide")), ["SAFE", "move-aside", "hot"]);
  assert.deepEqual(pick(familyTogglePolicy("cs2", null)), ["SAFE", "move-aside", "restart"]);
  assert.deepEqual(pick(familyTogglePolicy("valheim", "bepinex")), ["SAFE_WITH_WARNING", "move-aside", "restart"]);
  assert.deepEqual(pick(familyTogglePolicy("factorio", null)), ["SAFE_WITH_WARNING", "native-flag", "restart"]);
  assert.deepEqual(pick(familyTogglePolicy("corekeeper", null)), ["SAFE_WITH_WARNING", "move-aside", "restart"]);
});
const pick = (p: { safety: string; strategy: string; restart: string }) => [p.safety, p.strategy, p.restart];

test("content risk: content categories warn, server-side categories don't, unknown errs to warn", () => {
  const m = (category: string, categories: string[] = [], loaders: string[] = []) => ({ name: "X", category, categories, loaders });
  assert.equal(contentRisk("minecraft", "fabric", m("Mods", ["worldgen"])).risk, true);
  assert.equal(contentRisk("minecraft", "fabric", m("Mods", ["optimization"])).risk, false);
  assert.equal(contentRisk("minecraft", "fabric", m("Mods", ["library"])).risk, false);
  assert.equal(contentRisk("minecraft", "fabric", m("Mods", [])).risk, true, "unknown → treat as content");
  assert.equal(contentRisk("minecraft", "paper", m("Plugins", ["worldgen"])).risk, false, "Paper plugins: SAFE family");
  assert.equal(contentRisk("valheim", "bepinex", m("Content")).risk, true);
  assert.equal(contentRisk("valheim", "bepinex", m("Building")).risk, true);
  assert.equal(contentRisk("valheim", "bepinex", m("Tweaks")).risk, false);
  assert.equal(contentRisk("valheim", "bepinex", m("Admin")).risk, false);
  assert.equal(contentRisk("factorio", null, m("Mods")).risk, true);
  assert.equal(contentRisk("corekeeper", null, m("Quality of Life")).risk, false);
  assert.equal(contentRisk("corekeeper", null, m("Item")).risk, true);
  assert.equal(contentRisk("rust", "oxide", m("Plugins")).risk, false);
  assert.equal(contentRisk("minecraft", "vanilla", m("Datapacks", [], ["datapack"])).risk, true);
});

test("toggleDecision: allowed only for engine installs, never for modpacks; ack only for content risk", () => {
  const plugin = { name: "LuckPerms", category: "Admin", categories: ["management"], loaders: ["paper"] };
  const d1 = toggleDecision({ family: "minecraft", variant: "paper", mod: plugin, engine: true });
  assert.ok(d1.allowed && d1.safety === "SAFE" && !d1.needsAck && d1.warning === null);

  const content = { name: "Create", category: "Mods", categories: ["technology", "decoration"], loaders: ["fabric"] };
  const d2 = toggleDecision({ family: "minecraft", variant: "fabric", mod: content, engine: true });
  assert.ok(d2.allowed && d2.safety === "SAFE_WITH_WARNING" && d2.needsAck && d2.contentRisk);
  assert.match(d2.warning!, /does NOT bring them back/);

  const perf = { name: "Lithium", category: "Mods", categories: ["optimization"], loaders: ["fabric"] };
  const d3 = toggleDecision({ family: "minecraft", variant: "fabric", mod: perf, engine: true });
  assert.ok(d3.allowed && d3.safety === "SAFE" && !d3.needsAck);
  assert.ok(d3.warning, "family caveat still shown");

  const pack = { name: "Fabulously Optimized", category: "Modpacks", categories: [], loaders: ["mrpack"] };
  assert.equal(isModpack(pack), true);
  assert.equal(toggleDecision({ family: "minecraft", variant: "fabric", mod: pack, engine: true }).allowed, false);
  assert.equal(toggleDecision({ family: "valheim", variant: "bepinex", mod: { name: "P", category: "Modpacks" }, engine: true }).allowed, false);

  assert.equal(toggleDecision({ family: "minecraft", variant: "paper", mod: plugin, engine: false }).allowed, false, "legacy install: no state file, no toggle");
  const ark = toggleDecision({ family: "ark", variant: null, mod: { name: "S+", category: "Mods" }, engine: false });
  assert.ok(!ark.allowed && /deletes its structures/.test(ark.reason));
});

/* ── dependency planning ──────────────────────────────────────────────────── */

test("planToggles: blocks disabling a needed mod, orders dependents first, enables dependencies first", () => {
  const graph = { a: ["lib"], b: ["a", "lib"], lib: [] };
  const names = { a: "A", b: "B", lib: "Lib" };
  const all = new Set(["a", "b", "lib"]);

  const bad = planToggles([{ modId: "lib", op: "disable" }], graph, all, names);
  assert.equal(bad.ok, false);
  assert.match(bad.problems[0], /A, B need Lib/);

  const good = planToggles([{ modId: "lib", op: "disable" }, { modId: "a", op: "disable" }, { modId: "b", op: "disable" }], graph, all, names);
  assert.ok(good.ok, good.problems.join());
  assert.deepEqual(good.order.map((o) => o.modId), ["b", "a", "lib"]);

  const enMissing = planToggles([{ modId: "b", op: "enable" }], graph, new Set(), names);
  assert.equal(enMissing.ok, false);
  assert.match(enMissing.problems[0], /B needs A, Lib/);

  const en = planToggles([{ modId: "b", op: "enable" }, { modId: "lib", op: "enable" }, { modId: "a", op: "enable" }], graph, new Set(), names);
  assert.ok(en.ok);
  assert.deepEqual(en.order.map((o) => o.modId), ["lib", "a", "b"]);

  // a dependency that isn't installed via Nxeon (not in names) never blocks
  assert.ok(planToggles([{ modId: "x", op: "enable" }], { x: ["ghost"] }, new Set(), { x: "X" }).ok);
});

test("batch: payload parsing, worker ordering, validation", () => {
  assert.deepEqual(batchOpsFromPayload({ op: "disable", modId: "m1" }), [{ modId: "m1", op: "disable" }]);
  assert.deepEqual(batchOpsFromPayload({ ops: [{ modId: "a", op: "enable" }, { bogus: 1 }] }), [{ modId: "a", op: "enable" }]);
  const rows = [{ modId: "a" }, { modId: "b" }, { modId: "c" }, { modId: "z" }];
  assert.deepEqual(orderPendingByPlan(rows, { ops: [{ modId: "c", op: "disable" }, { modId: "a", op: "disable" }, { modId: "b", op: "enable" }] }).map((r) => r.modId), ["c", "a", "b", "z"]);
  assert.deepEqual(orderPendingByPlan(rows, { op: "install", modId: "c" }).map((r) => r.modId), ["a", "b", "c", "z"], "single op keeps order");

  const st = new Map<string, string | null>([["a", "INSTALLED"], ["b", "DISABLED"], ["c", "INSTALLING"]]);
  const nm = new Map([["a", "A"], ["b", "B"], ["c", "C"]]);
  assert.equal(validateBatch([{ modId: "a", op: "disable" }, { modId: "b", op: "enable" }], st, nm), null);
  assert.match(validateBatch([{ modId: "b", op: "disable" }], st, nm)!, /B is disabled/);
  assert.match(validateBatch([{ modId: "c", op: "remove" }], st, nm)!, /C is installing/);
  assert.match(validateBatch([{ modId: "a", op: "disable" }, { modId: "a", op: "remove" }], st, nm)!, /only appear once/);
  assert.match(validateBatch([{ modId: "q", op: "enable" }], st, nm)!, /isn't installed/);
  assert.deepEqual(OP_FROM.disable, ["INSTALLED"]);
});

/* ── engine: safe, idempotent, rolled-back toggles ────────────────────────── */

const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const BASE = "/opt/game";
const PLUG = `${BASE}/plugins`;

function guest() {
  const root = mkdtempSync(path.join(tmpdir(), "nxeon-toggle-test-"));
  mkdirSync(path.join(root, PLUG.slice(1)), { recursive: true });
  return { root, fs: new LocalGuestFs(root), at: (p: string) => path.join(root, p.slice(1)) };
}

function fakeInstaller(extra: Partial<FamilyInstaller> = {}): FamilyInstaller {
  return {
    family: "testgame",
    sources: ["test"],
    mechanism: "test",
    restartRequired: true,
    compat: () => ({ verdict: "ok", detail: "" }),
    detect: async () => ({ base: BASE, dirs: { plugins: PLUG }, gameVersion: null }),
    resolve: async () => ({ error: "not used" }),
    place: async () => ({ error: "not used" }),
    ...extra,
  };
}

const server: ServerFacts = { id: "s1", family: "testgame", variant: null, pinnedVersion: null, config: null };
const modFacts = (id: string, name: string): CatalogFacts => ({ id, gameFamily: "testgame", slug: id, name, source: "test", sourceId: id, url: null, category: "Mods", appliesToVariant: null, loaders: [], gameVersions: [], serverSide: null });

/** Put packages on the fake guest exactly as the engine would have, plus state.json. */
function seed(g: ReturnType<typeof guest>, pkgs: { id: string; key: string; name: string; files: string[]; requires?: string[]; disabled?: boolean }[]) {
  const state: GuestState = { v: 1, family: "testgame", packages: {}, roots: {} };
  for (const p of pkgs) {
    const files = p.files.map((rel) => {
      const abs = `${PLUG}/${rel}`;
      const data = `bytes of ${rel}`;
      const at = p.disabled ? g.at(`/root/.nxeon-mods/disabled/${p.key.replace(/[^A-Za-z0-9._-]/g, "_")}${abs}`) : g.at(abs);
      mkdirSync(path.dirname(at), { recursive: true });
      writeFileSync(at, data);
      return { path: abs, sha256: sha(data), size: Buffer.byteLength(data) };
    });
    state.packages[p.key] = { key: p.key, name: p.name, version: "1.0", versionId: null, files, roots: [p.id], requires: p.requires ?? [], incompatible: [], disabled: !!p.disabled, installedAt: "", updatedAt: "" };
    state.roots[p.id] = { key: p.key, name: p.name };
  }
  mkdirSync(path.dirname(g.at(STATE_PATH)), { recursive: true });
  writeFileSync(g.at(STATE_PATH), JSON.stringify(state));
}

test("engine toggle: disable → idempotent repeat → enable, files moved aside and back", async () => {
  const g = guest();
  try {
    seed(g, [{ id: "m1", key: "t:one", name: "One", files: ["one/One.dll", "one/assets.bin"] }]);
    const inst = fakeInstaller();
    const d = await setDisabled(inst, modFacts("m1", "One"), server, { fs: g.fs, fetcher: never }, true);
    assert.ok(d.ok, JSON.stringify(d));
    assert.ok(!existsSync(g.at(`${PLUG}/one/One.dll`)));
    assert.ok(existsSync(g.at(`/root/.nxeon-mods/disabled/t_one${PLUG}/one/One.dll`)));
    assert.ok(!existsSync(g.at(`${PLUG}/one`)), "empty folder tidied");
    assert.equal((await loadState(g.fs, "testgame")).packages["t:one"].disabled, true);

    const again = await setDisabled(inst, modFacts("m1", "One"), server, { fs: g.fs, fetcher: never }, true);
    assert.ok(again.ok && again.changed.length === 0 && again.restartRequired === false, "idempotent");

    const e = await setDisabled(inst, modFacts("m1", "One"), server, { fs: g.fs, fetcher: never }, false);
    assert.ok(e.ok, JSON.stringify(e));
    assert.equal(readFileSync(g.at(`${PLUG}/one/One.dll`), "utf8"), "bytes of one/One.dll");
    assert.ok(!existsSync(g.at(`/root/.nxeon-mods/disabled/t_one`)));
    assert.equal((await loadState(g.fs, "testgame")).packages["t:one"].disabled, false);
  } finally {
    rmSync(g.root, { recursive: true, force: true });
  }
});

test("engine toggle: a failure part-way rolls every moved file back and leaves state untouched", async () => {
  const g = guest();
  try {
    seed(g, [{ id: "m1", key: "t:one", name: "One", files: ["one/a.dll", "one/b.dll", "one/c.dll"] }]);
    let renames = 0;
    const flaky = new LocalGuestFs(g.root);
    const orig = flaky.rename.bind(flaky);
    flaky.rename = async (from: string, to: string) => {
      if (++renames === 3) throw new Error("disk full");
      return orig(from, to);
    };
    const r = await setDisabled(fakeInstaller(), modFacts("m1", "One"), server, { fs: flaky, fetcher: never }, true);
    assert.ok(!r.ok && /rolled back: disk full/.test(r.error), JSON.stringify(r));
    for (const f of ["a", "b", "c"]) assert.ok(existsSync(g.at(`${PLUG}/one/${f}.dll`)), `${f} back in place`);
    assert.equal((await loadState(g.fs, "testgame")).packages["t:one"].disabled, false);
  } finally {
    rmSync(g.root, { recursive: true, force: true });
  }
});

test("engine toggle: finishes an interrupted earlier attempt instead of refusing", async () => {
  const g = guest();
  try {
    seed(g, [{ id: "m1", key: "t:one", name: "One", files: ["one/a.dll", "one/b.dll"] }]);
    // Simulate a crash after the first file moved but before state.json was written.
    const aside = g.at(`/root/.nxeon-mods/disabled/t_one${PLUG}/one/a.dll`);
    mkdirSync(path.dirname(aside), { recursive: true });
    writeFileSync(aside, readFileSync(g.at(`${PLUG}/one/a.dll`)));
    rmSync(g.at(`${PLUG}/one/a.dll`));
    const r = await setDisabled(fakeInstaller(), modFacts("m1", "One"), server, { fs: g.fs, fetcher: never }, true);
    assert.ok(r.ok, JSON.stringify(r));
    assert.ok(!existsSync(g.at(`${PLUG}/one/b.dll`)));
    assert.equal((await loadState(g.fs, "testgame")).packages["t:one"].disabled, true);
  } finally {
    rmSync(g.root, { recursive: true, force: true });
  }
});

test("engine toggle: refuses a missing file and a hand-placed file without changing anything", async () => {
  const g = guest();
  try {
    seed(g, [{ id: "m1", key: "t:one", name: "One", files: ["one/a.dll"] }]);
    rmSync(g.at(`${PLUG}/one/a.dll`));
    const r = await setDisabled(fakeInstaller(), modFacts("m1", "One"), server, { fs: g.fs, fetcher: never }, true);
    assert.ok(!r.ok && /missing/.test(r.error));

    const g2 = guest();
    seed(g2, [{ id: "m1", key: "t:one", name: "One", files: ["one/a.dll"], disabled: true }]);
    writeFileSync(g2.at(`${PLUG}/one-a-copy`), "x");
    mkdirSync(g2.at(`${PLUG}/one`), { recursive: true });
    writeFileSync(g2.at(`${PLUG}/one/a.dll`), "someone put this back by hand");
    const e = await setDisabled(fakeInstaller(), modFacts("m1", "One"), server, { fs: g2.fs, fetcher: never }, false);
    assert.ok(!e.ok && /already exists/.test(e.error));
    assert.equal(readFileSync(g2.at(`${PLUG}/one/a.dll`), "utf8"), "someone put this back by hand");
    rmSync(g2.root, { recursive: true, force: true });
  } finally {
    rmSync(g.root, { recursive: true, force: true });
  }
});

test("engine toggle: dependency rules both ways + dependencyGraph", async () => {
  const g = guest();
  try {
    seed(g, [
      { id: "lib", key: "t:lib", name: "Lib", files: ["lib.dll"] },
      { id: "a", key: "t:a", name: "A", files: ["a.dll"], requires: ["t:lib"] },
    ]);
    const inst = fakeInstaller();
    const blocked = await setDisabled(inst, modFacts("lib", "Lib"), server, { fs: g.fs, fetcher: never }, true);
    assert.ok(!blocked.ok && /A needs Lib/.test(blocked.error));
    assert.ok(existsSync(g.at(`${PLUG}/lib.dll`)));

    assert.ok((await setDisabled(inst, modFacts("a", "A"), server, { fs: g.fs, fetcher: never }, true)).ok);
    assert.ok((await setDisabled(inst, modFacts("lib", "Lib"), server, { fs: g.fs, fetcher: never }, true)).ok);
    const enA = await setDisabled(inst, modFacts("a", "A"), server, { fs: g.fs, fetcher: never }, false);
    assert.ok(!enA.ok && /needs Lib, which is disabled/.test(enA.error), JSON.stringify(enA));

    const st = await loadState(g.fs, "testgame");
    assert.deepEqual(dependencyGraph(st), { lib: [], a: ["lib"] });
  } finally {
    rmSync(g.root, { recursive: true, force: true });
  }
});

test("engine toggle (Valheim): disable and uninstall also remove the image's synced copy, only when byte-identical", async () => {
  const g = guest();
  try {
    const VP = "/opt/valheim/config/bepinex/plugins";
    const inst = fakeInstaller({ syncedCopy: valheimSyncedCopy, syncedRoot: VALHEIM_SYNCED_PLUGINS, detect: async () => ({ base: "/opt/valheim/config", dirs: { plugins: VP }, gameVersion: null }) });
    const state: GuestState = { v: 1, family: "testgame", packages: {}, roots: {} };
    const put = (abs: string, data: string) => {
      mkdirSync(path.dirname(g.at(abs)), { recursive: true });
      writeFileSync(g.at(abs), data);
    };
    put(`${VP}/Auth-Mod/Mod.dll`, "MOD");
    put(`${VP}/Auth-Mod/Extra.dll`, "EXTRA");
    put(`${VALHEIM_SYNCED_PLUGINS}/Auth-Mod/Mod.dll`, "MOD"); // what the image copied
    put(`${VALHEIM_SYNCED_PLUGINS}/Auth-Mod/Extra.dll`, "CHANGED BY SOMEONE"); // differs → must survive
    state.packages["ts:Auth-Mod"] = {
      key: "ts:Auth-Mod", name: "Mod", version: "1", versionId: null, roots: ["vm"], requires: [], incompatible: [], disabled: false, installedAt: "", updatedAt: "",
      files: [{ path: `${VP}/Auth-Mod/Mod.dll`, sha256: sha("MOD"), size: 3 }, { path: `${VP}/Auth-Mod/Extra.dll`, sha256: sha("EXTRA"), size: 5 }],
    };
    state.roots.vm = { key: "ts:Auth-Mod", name: "Mod" };
    put(STATE_PATH, JSON.stringify(state));

    assert.equal(valheimSyncedCopy(`${VP}/Auth-Mod/Mod.dll`), `${VALHEIM_SYNCED_PLUGINS}/Auth-Mod/Mod.dll`);
    assert.equal(valheimSyncedCopy("/etc/passwd"), null);

    const d = await setDisabled(inst, modFacts("vm", "Mod"), server, { fs: g.fs, fetcher: never }, true);
    assert.ok(d.ok, JSON.stringify(d));
    assert.ok(!existsSync(g.at(`${VALHEIM_SYNCED_PLUGINS}/Auth-Mod/Mod.dll`)), "synced copy removed → stays off on old images");
    assert.equal(readFileSync(g.at(`${VALHEIM_SYNCED_PLUGINS}/Auth-Mod/Extra.dll`), "utf8"), "CHANGED BY SOMEONE");

    assert.ok((await setDisabled(inst, modFacts("vm", "Mod"), server, { fs: g.fs, fetcher: never }, false)).ok);
    put(`${VALHEIM_SYNCED_PLUGINS}/Auth-Mod/Mod.dll`, "MOD"); // next start re-syncs it
    const u = await uninstall(inst, modFacts("vm", "Mod"), server, { fs: g.fs, fetcher: never });
    assert.ok(u.ok, JSON.stringify(u));
