# replace header imports/helpers
head_new='''"use client";

import { useCallback, useEffect, useRef, useState, useTransition, useMemo } from "react";
import { Icon } from "@/components/nx/Icon";
import {
  checkModUpdates,
  getModsOverview,
  panelApplyModBatch,
  panelInstallMod,
  panelRemoveMod,
  panelUpdateMod,
  previewModInstall,
  type InstallPreview,
  type InstalledMod,
  type ModsOverview,
} from "@/lib/actions-mod-installs";
import { createGameBackup, gamePower } from "@/lib/actions-game-control";
import type { ModLoad } from "@/lib/mod-load";
import type { Compat } from "@/lib/mods/types";
import type { BrowseCard } from "@/lib/mods-browse";
import { ModBrowser } from "@/components/customer/mods/browser/ModBrowser";
import { Chip, InstalledLibrary, ModIcon, PENDING, SOURCE_LABEL, fileSize, type StagedOp } from "./mods/InstalledLibrary";

/**
 * Mods & Plugins — two areas:
 *
 *  INSTALLED MODS (./mods/InstalledLibrary.tsx): the server's library —
 *    version, source, size, health, updates, dependencies, uninstall, and an
 *    on/off switch ONLY where the vetting (lib/mods/toggle-policy.ts) says a
 *    game supports disabling without uninstalling. Switches stage changes;
 *    they're applied together as one job. Content-adding mods need an
 *    explicit acknowledgement and are offered a world backup first.
 *  MOD STORE (components/customer/mods/browser/*): the whole catalogue for
 *    this game, searched in the DB, with compatibility for THIS server's
 *    loader + version and a live dependency preview before install.
 *
 * Honesty rules: every number is the source's own or absent; a change the
 * worker could not apply comes back as a failure with its reason; when
 * one-click changes are switched off (ENABLE_REAL_GAMEMODS) the tab says so
 * and offers no button that would only fail.
 */

const PLUGIN_CATS = ["admin", "permission", "protection", "economy", "chat", "discord", "core", "utility", "clan", "rank", "teleport", "plugins"];

const LOAD_STYLE: Record<string, { ring: string; ink: string; icon: string; label: string }> = {
  fine: { ring: "border-rim-hi bg-well", ink: "text-tx-dim", icon: "checkcircle", label: "Load looks fine" },
  watch: { ring: "border-sky-500/35 bg-sky-500/[0.07]", ink: "text-sky-300", icon: "warncircle", label: "Worth watching" },
  high: { ring: "border-amber-500/45 bg-amber-500/[0.09]", ink: "text-amber-300", icon: "warntriangle", label: "Heavy for this tier" },
};

function LoadBanner({ load }: { load: ModLoad }) {
  if (load.count === 0) return null;
  const st = LOAD_STYLE[load.level];
  return (
    <div className={"flex flex-wrap items-start gap-3.5 rounded-[14px] border px-4 py-3.5 " + st.ring}>
      <span className={"grid h-[32px] w-[32px] flex-none place-items-center rounded-[10px] border border-white/10 bg-white/[0.05] " + st.ink}>
        <Icon name={st.icon} size={15} tone="inherit" />
      </span>
      <div className="min-w-0 flex-1">
        <p className={"text-[13px] font-bold " + st.ink}>{st.label}</p>
        <p className="mt-0.5 text-[12.5px] leading-relaxed text-tx-dim">{load.headline}</p>
        {load.advice && <p className="mt-1.5 max-w-[74ch] text-[12px] leading-relaxed text-tx-faint">{load.advice}</p>}
      </div>
      {load.percentOfRam !== null && (
        <div className="flex flex-none flex-col items-end">
          <span className={"num text-[19px] font-extrabold leading-none " + st.ink}>{load.percentOfRam}%</span>
          <span className="mt-1 text-[10px] font-bold uppercase tracking-[0.12em] text-tx-faint">of RAM, on disk</span>
        </div>
      )}
    </div>
  );
}

/** What the install dialog needs — satisfied by a browser card. */
type InstallTarget = { id: string; name: string; source: string; iconUrl: string | null; compat: Compat | null; impact: string; impactNote: string | null; url: string | null };
const fromCard = (m: BrowseCard): InstallTarget => ({ id: m.id, name: m.name, source: m.source, iconUrl: m.icon, compat: m.compat, impact: m.impact, impactNote: null, url: null });

type Area = "installed" | "store";

'''
body='''export function ModsPanel({ serverId, scope }: { serverId: string; scope: "mods" | "plugins" }) {
  const [ov, setOv] = useState<ModsOverview | null>(null);
  const [fatal, setFatal] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [area, setArea] = useState<Area | null>(null);
  const [total, setTotal] = useState<number | null>(null);
  const [refreshKey, setRefreshKey] = useState(0);
  const [confirm, setConfirm] = useState<InstallTarget | null>(null);
  const [removing, setRemoving] = useState<InstalledMod | null>(null);
  const [riskBatch, setRiskBatch] = useState<{ changes: { modId: string; op: StagedOp }[]; risky: InstalledMod[] } | null>(null);
  const [updates, setUpdates] = useState<Record<string, string | null> | null>(null);
  const [checking, setChecking] = useState(false);
  const [restarting, setRestarting] = useState(false);
  const [, start] = useTransition();

  const loadOverview = useCallback(async () => {
    const r = await getModsOverview(serverId).catch(() => ({ error: "Couldn't load your mods." }) as { error: string });
    if ("view" in r && r.view) {
      setOv(r.view);
      setFatal(null);
    } else if ("error" in r && r.error) setFatal(r.error);
  }, [serverId]);

  useEffect(() => { void loadOverview(); }, [loadOverview]);

  // First view: the library when there is one, the store when there isn't.
  useEffect(() => {
    if (ov && area === null) setArea(ov.installed.some((m) => m.status !== "REMOVED") ? "installed" : "store");
  }, [ov, area]);

  // Plugins view = the catalogue's admin-ish categories (a filter, said plainly).
  const pluginCategory = useMemo(() => {
    if (scope !== "plugins" || !ov) return null;
    return ov.categories.find((c) => PLUGIN_CATS.some((k) => c.category.toLowerCase().includes(k)))?.category ?? null;
  }, [scope, ov]);

  // Follow the job while one is queued/running, then refresh the store's results once.
  const active = !!ov?.job || (ov?.installed ?? []).some((m) => m.status && PENDING.has(m.status));
  const wasActive = useRef(false);
  useEffect(() => {
    if (!active) {
      if (wasActive.current) {
        wasActive.current = false;
        setRefreshKey((k) => k + 1);
      }
      return;
    }
    wasActive.current = true;
    const t = setInterval(() => void loadOverview(), 3000);
    return () => clearInterval(t);
  }, [active, loadOverview]);

  const run = (fn: () => Promise<{ error?: string } | null | undefined>, ok?: string) =>
    start(async () => {
      setError(null);
      setNotice(null);
      const r = await fn().catch(() => ({ error: "Couldn't reach the server." }));
      if (r && r.error) setError(r.error);
      else if (ok) setNotice(ok);
      await loadOverview();
      setRefreshKey((k) => k + 1);
    });

  const install = (m: InstallTarget, ackClient: boolean) => {
    setConfirm(null);
    run(() => panelInstallMod(serverId, m.id, { ackClient }), `Installing ${m.name} — it will appear under Installed mods.`);
  };
  const applyBatch = (changes: { modId: string; op: StagedOp }[], ackRisk: boolean) => {
    setRiskBatch(null);
    run(() => panelApplyModBatch(serverId, changes, { ackRisk }));
  };

  const restartNow = () =>
    start(async () => {
      setRestarting(true);
      setError(null);
      const r = await gamePower(serverId, "restart").catch(() => ({ ok: false as const, error: "Couldn't reach the server." }));
      if (!r.ok) setError(r.error);
      await loadOverview();
      setRestarting(false);
    });

  const doCheckUpdates = () =>
    start(async () => {
      setChecking(true);
      const r = await checkModUpdates(serverId).catch(() => ({ error: "Couldn't check for updates." }) as { error: string });
      if ("updates" in r && r.updates) setUpdates(r.updates);
      else if ("error" in r && r.error) setError(r.error);
      setChecking(false);
    });

  if (!ov && !fatal) {
    return <div className="rounded-[16px] border border-rim-hi bg-well px-6 py-16 text-center text-[13px] text-tx-dim">Loading mods…</div>;
  }
  if (!ov) {
    return (
      <div className="rounded-[16px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-6 py-14 text-center">
        <Icon name="cube" size={28} className="mx-auto" />
        <p className="mt-3 text-[14.5px] font-bold text-white">Mods aren&apos;t available for this game</p>
        <p className="mx-auto mt-1.5 max-w-[52ch] text-[12.5px] leading-relaxed text-tx-dim">{fatal}</p>
      </div>
    );
  }

  const unavailable = ov.coverage.mode === "unavailable";
  const installedVisible = ov.installed.filter((m) => m.status !== "REMOVED");
  const enabledCount = installedVisible.filter((m) => m.status === "INSTALLED").length;
  const disabledCount = installedVisible.filter((m) => m.status === "DISABLED").length;
  const cur: Area = area ?? "installed";

  return (
    <div className="flex flex-col gap-4">
      {/* ── banner ───────────────────────────────────────────────────── */}
      <div className="nx-dark-island overflow-hidden rounded-[17px] border border-[#7b3fef]/40 bg-[linear-gradient(140deg,rgba(90,40,200,.35),rgba(20,36,110,.28)_58%,rgba(4,12,34,.5))] p-4 sm:p-5">
        <div className="flex flex-wrap items-start gap-4 sm:gap-5">
          <span className="grid h-[48px] w-[48px] flex-none place-items-center rounded-[14px] border border-white/15 bg-white/10">
            <Icon name="cube" size={21} tone="inherit" className="text-fuchsia-300" />
          </span>
          <div className="min-w-0 flex-1">
            <div className="flex flex-wrap items-center gap-2">
              <h2 className="text-[19px] font-extrabold tracking-[-0.02em] text-white">Mods &amp; Plugins</h2>
              {unavailable ? (
                <Chip cls="border-white/20 bg-white/[0.07] text-white/70">Manual install</Chip>
              ) : !ov.installsLive ? (
                <Chip cls="border-amber-400/45 bg-amber-400/10 text-amber-200" icon="lock">One-click paused</Chip>
              ) : (
                <Chip cls="border-cyan-400/40 bg-cyan-400/10 text-cyan-200" icon="bolt">One-click</Chip>
              )}
            </div>
            <p className="mt-1.5 max-w-[68ch] text-[12.5px] leading-relaxed text-white/75">
              {unavailable
                ? ov.coverage.text
                : <>Your installed mods and the full {ov.familyName} store in one place. {ov.coverage.mode === "engine" ? <>We fetch the right build for your server from the mod&apos;s own source, check it, pull in its dependencies and back up anything it changes. </> : null}<span className="text-white/55">{ov.coverage.text}</span></>}
            </p>
            <p className="mt-2 flex flex-wrap items-center gap-2 text-[11.5px] text-white/60">
              <span className="rounded-[6px] border border-white/15 bg-white/[0.07] px-2 py-0.5 font-semibold text-white/85">
                {ov.variant ?? "server"}{ov.gameVersion ? ` · ${ov.gameVersion}` : ""}
              </span>
              compatibility is checked against this
            </p>
          </div>
          <dl className="flex flex-none gap-6">
            <div className="flex flex-col">
              <dt className="text-[10px] font-bold uppercase tracking-[0.14em] text-white/50">Enabled</dt>
              <dd className="num text-[22px] font-extrabold leading-none text-white">{enabledCount}</dd>
            </div>
            {disabledCount > 0 && (
              <div className="flex flex-col">
                <dt className="text-[10px] font-bold uppercase tracking-[0.14em] text-white/50">Off</dt>
                <dd className="num text-[22px] font-extrabold leading-none text-white/70">{disabledCount}</dd>
              </div>
            )}
            <div className="flex flex-col">
              <dt className="text-[10px] font-bold uppercase tracking-[0.14em] text-white/50">In store</dt>
              <dd className="num text-[22px] font-extrabold leading-none text-white">{ov.catalogTotal.toLocaleString()}</dd>
            </div>
          </dl>
        </div>
      </div>

      {!unavailable && !ov.installsLive && (
        <div className="flex items-start gap-3 rounded-[14px] border border-amber-500/40 bg-amber-500/[0.08] px-4 py-3.5" role="status">
          <Icon name="lock" size={15} tone="inherit" className="mt-0.5 text-amber-300" />
          <div className="min-w-0 text-[12.5px] leading-relaxed text-amber-100/90">
            <p className="font-bold text-amber-200">One-click mod changes aren&apos;t switched on yet</p>
            <p className="mt-0.5">You can browse the store and see what&apos;s installed, but installing, updating, switching off or removing from here is paused — nothing would be applied. Add mods by hand in the <strong className="font-semibold">Files</strong> tab meanwhile.</p>
          </div>
        </div>
      )}

      {/* ── job progress ─────────────────────────────────────────────── */}
      {ov.job && (
        <div className="rounded-[14px] border border-sky-500/35 bg-sky-500/[0.07] px-4 py-3" role="status" aria-live="polite">
          <div className="flex items-center gap-2.5">
            <Icon name="refresh" size={14} tone="inherit" className="animate-spin text-sky-300" />
            <p className="min-w-0 flex-1 truncate text-[12.5px] font-semibold text-sky-200">
              {ov.job.status === "QUEUED" ? "Queued — waiting for the server to be free" : ov.backupRunning ? "Backing up your world…" : ov.job.step ?? "Working…"}
            </p>
            <span className="num text-[12px] font-bold text-sky-300">{ov.job.progress}%</span>
          </div>
          <div className="mt-2 h-[5px] overflow-hidden rounded-full bg-white/[0.08]">
            <div className="h-full rounded-full bg-[linear-gradient(90deg,#3b6be8,#7b3fef)] transition-all duration-700" style={{ width: `${Math.max(4, ov.job.progress)}%` }} />
          </div>
        </div>
      )}

      {/* ── restart prompt ───────────────────────────────────────────── */}
      {!ov.job && ov.restart.required && (
        <div className="flex flex-wrap items-center gap-3 rounded-[14px] border border-amber-500/45 bg-amber-500/[0.09] px-4 py-3.5" role="status">
          <Icon name="warntriangle" size={16} tone="inherit" className="text-amber-300" />
          <div className="min-w-0 flex-1">
            <p className="text-[13px] font-bold text-amber-200">Restart required to load your mod changes</p>
            {ov.restart.changed.length > 0 && (
              <p className="mt-0.5 line-clamp-2 text-[12px] text-amber-200/75">{ov.restart.changed.slice(0, 6).join(" · ")}</p>
            )}
          </div>
          <button type="button" onClick={restartNow} disabled={restarting || !ov.serverRunning} className="nx-cta px-4 py-2 text-[12.5px] disabled:opacity-50">
            {restarting ? "Restarting…" : "Restart now"}
          </button>
        </div>
      )}

      <LoadBanner load={ov.load} />

      {error && <p className="rounded-[11px] border border-red-500/35 bg-red-500/10 px-3.5 py-2.5 text-[12.5px] text-red-300" role="alert">{error}</p>}
      {notice && !error && <p className="rounded-[11px] border border-emerald-500/30 bg-emerald-500/[0.08] px-3.5 py-2.5 text-[12.5px] text-emerald-200" role="status">{notice}</p>}

      {/* ── the two areas ────────────────────────────────────────────── */}
      <div className="grid grid-cols-2 gap-2 sm:flex sm:gap-2.5" role="tablist" aria-label="Mods">
        {([
          ["installed", "layers", "Installed mods", `${installedVisible.length} on this server`],
          ["store", "cart", "Mod store", total === null ? `${ov.catalogTotal.toLocaleString()} for ${ov.familyName}` : `${total.toLocaleString()} match`],
        ] as const).map(([k, icon, label, sub]) => (
          <button key={k} type="button" role="tab" aria-selected={cur === k} onClick={() => setArea(k)}
            className={"flex min-w-0 items-center gap-2.5 rounded-[13px] border px-3.5 py-2.5 text-left transition sm:min-w-[210px] " + (cur === k ? "border-[#7b3fef]/60 bg-[linear-gradient(140deg,rgba(123,63,239,.28),rgba(59,107,232,.14))] shadow-[0_10px_30px_-18px_rgba(123,63,239,.9)]" : "border-rim-hi bg-[rgba(6,14,36,.6)] hover:border-brand-400/40")}>
            <span className={"grid h-[30px] w-[30px] flex-none place-items-center rounded-[9px] border " + (cur === k ? "border-white/20 bg-white/10 text-cyan-200" : "border-rim-hi bg-well text-tx-dim")}>
              <Icon name={icon} size={14} tone="inherit" />
            </span>
            <span className="min-w-0">
              <span className={"block truncate text-[13px] font-bold " + (cur === k ? "text-white" : "text-tx-dim")}>{label}</span>
              <span className="block truncate text-[11px] text-tx-faint">{sub}</span>
            </span>
          </button>
        ))}
      </div>

      {cur === "installed" ? (
        <InstalledLibrary
          ov={ov}
          busy={!!ov.job}
          updates={updates}
          checking={checking}
          onCheckUpdates={doCheckUpdates}
          onUpdate={(m) => run(() => panelUpdateMod(serverId, m.id), `Updating ${m.name}…`)}
          onRemove={(m) => setRemoving(m)}
          onApply={(changes, risky) => (risky.length ? setRiskBatch({ changes, risky }) : applyBatch(changes, false))}
        />
      ) : (
        <ModBrowser
          serverId={serverId}
          scope={scope}
          unavailable={unavailable}
          jobActive={!!ov.job || !ov.installsLive}
          refreshKey={refreshKey}
          defaultCategory={pluginCategory}
          catalogTotal={ov.catalogTotal}
          onInstall={(m) => setConfirm(fromCard(m))}
          onAct={(modId, op) => {
            if (op === "remove") run(() => panelRemoveMod(serverId, modId));
            else if (op === "update") run(() => panelUpdateMod(serverId, modId));
            else if (op === "enable" || op === "disable") setArea("installed");
          }}
          onTotal={setTotal}
        />
      )}

      <p className="text-[11.5px] leading-relaxed text-tx-faint">
        Anything not in the store can still be installed by hand: upload it in the <strong className="text-tx-dim">Files</strong> tab and restart from <strong className="text-tx-dim">Console</strong>. Before changing files we keep a backup on your server in <span className="font-mono text-tx-dim">/root/.nxeon-mods/backups</span>.
      </p>

      {confirm && <InstallDialog serverId={serverId} mod={confirm} load={ov.load} live={ov.installsLive} onCancel={() => setConfirm(null)} onConfirm={(ack) => install(confirm, ack)} />}
      {removing && (
        <RemoveDialog m={removing} onCancel={() => setRemoving(null)}
          onConfirm={() => { const m = removing; setRemoving(null); run(() => panelRemoveMod(serverId, m.id), `Removing ${m.name}…`); }} />
      )}
      {riskBatch && (
        <RiskDialog
          serverId={serverId}
          ov={ov}
          risky={riskBatch.risky}
          count={riskBatch.changes.length}
          onCancel={() => setRiskBatch(null)}
          onConfirm={() => applyBatch(riskBatch.changes, true)}
          onBackedUp={() => void loadOverview()}
        />
      )}
    </div>
  );
}

function Modal({ label, onCancel, children }: { label: string; onCancel: () => void; children: React.ReactNode }) {
  useEffect(() => {
    const k = (e: KeyboardEvent) => e.key === "Escape" && onCancel();
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [onCancel]);
  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-black/65 p-4 backdrop-blur-sm" role="dialog" aria-modal="true" aria-label={label} onClick={(e) => e.target === e.currentTarget && onCancel()}>
      <div className="nx-dark-island max-h-[88vh] w-full max-w-[500px] overflow-y-auto rounded-[17px] border border-[#7b3fef]/40 bg-[linear-gradient(180deg,rgba(14,26,56,.97),rgba(3,9,24,.98))] p-5">{children}</div>
    </div>
  );
}

function RemoveDialog({ m, onCancel, onConfirm }: { m: InstalledMod; onCancel: () => void; onConfirm: () => void }) {
  return (
    <Modal label={`Uninstall ${m.name}`} onCancel={onCancel}>
      <div className="flex items-start gap-3">
        <ModIcon m={m} size={40} />
        <div className="min-w-0">
          <h3 className="text-[15.5px] font-extrabold text-white">Uninstall {m.name}?</h3>
          <p className="mt-0.5 text-[12px] text-tx-faint">{m.version ? `v${m.version} · ` : ""}{SOURCE_LABEL[m.source] ?? m.source}</p>
        </div>
      </div>
      <div className="mt-4 flex flex-col gap-2 text-[12.5px] leading-relaxed text-tx-dim">
        <p>Its files are deleted from the server. Dependencies nothing else needs go too. Its config files stay, so a reinstall picks up your settings.</p>
        {m.neededBy.length > 0 && <p className="rounded-[10px] border border-amber-500/30 bg-amber-500/[0.07] px-3 py-2 text-amber-300">{m.neededBy.join(", ")} need{m.neededBy.length === 1 ? "s" : ""} this mod — remove {m.neededBy.length === 1 ? "it" : "them"} first.</p>}
        {m.toggle.allowed && m.toggle.contentRisk && <p className="rounded-[10px] border border-amber-500/30 bg-amber-500/[0.07] px-3 py-2 text-amber-300">This mod may add things to your world; they&apos;re deleted the next time those areas load and save without it. Back up the world first if you might want them.</p>}
        {m.toggle.allowed && m.status === "INSTALLED" && <p className="text-tx-faint">Only want it off for now? Use its switch instead — that keeps it installed.</p>}
      </div>
      <div className="mt-4 flex flex-wrap gap-2.5">
        <button type="button" onClick={onConfirm} disabled={m.neededBy.length > 0} className="rounded-[11px] border border-red-500/50 bg-red-500/15 px-5 py-2.5 text-[13px] font-bold text-red-200 transition hover:bg-red-500/25 disabled:opacity-50">Uninstall</button>
        <button type="button" onClick={onCancel} className="rounded-[11px] border border-rim-hi bg-well px-4 py-2.5 text-[13px] font-semibold text-tx-dim transition hover:text-white">Cancel</button>
      </div>
    </Modal>
  );
}

/**
 * Pre-change prompt for disabling content-adding mods: says exactly what can
 * be lost, offers a world backup FIRST (a real GAME_BACKUP job), and only
 * enables Apply once the owner ticks the acknowledgement. The server action
 * refuses the same change without that acknowledgement.
 */
function RiskDialog({ serverId, ov, risky, count, onCancel, onConfirm, onBackedUp }: {
  serverId: string; ov: ModsOverview; risky: InstalledMod[]; count: number; onCancel: () => void; onConfirm: () => void; onBackedUp: () => void;
}) {
  const [ack, setAck] = useState(false);
  const [backup, setBackup] = useState<"idle" | "queued" | "error">("idle");
  const [backupErr, setBackupErr] = useState<string | null>(null);
  const backingUp = backup === "queued" || ov.backupRunning;
  const startBackup = async () => {
    setBackupErr(null);
    const r = await createGameBackup(serverId).catch(() => ({ ok: false as const, error: "Couldn't reach the server." }));
    if (r.ok) { setBackup("queued"); onBackedUp(); }
    else { setBackup("error"); setBackupErr(r.error); }
  };
  const last = ov.lastWorldBackupAt ? new Date(ov.lastWorldBackupAt) : null;
  const recent = !!last && Date.now() - last.getTime() < 2 * 3600_000;
  return (
    <Modal label="Confirm disabling mods that add content" onCancel={onCancel}>
      <div className="flex items-start gap-3">
        <span className="grid h-[40px] w-[40px] flex-none place-items-center rounded-[12px] border border-amber-500/40 bg-amber-500/10 text-amber-300"><Icon name="warntriangle" size={17} tone="inherit" /></span>
        <div className="min-w-0">
          <h3 className="text-[15.5px] font-extrabold text-white">Some of these add things to your world</h3>
          <p className="mt-0.5 text-[12px] text-tx-faint">{count} change{count === 1 ? "" : "s"} ready to apply</p>
        </div>
      </div>
      <ul className="mt-4 flex flex-col gap-2">
        {risky.map((m) => (
          <li key={m.id} className="rounded-[11px] border border-amber-500/30 bg-amber-500/[0.06] px-3 py-2.5 text-[12.5px] leading-relaxed text-amber-100/90">
            <strong className="font-bold text-amber-200">{m.name}</strong>
            <span className="block text-[12px] text-amber-100/75">{m.toggle.allowed ? m.toggle.warning : null}</span>
          </li>
        ))}
      </ul>
      <div className="mt-3 rounded-[12px] border border-rim-hi bg-well px-3.5 py-3">
        <div className="flex flex-wrap items-center gap-2.5">
          <Icon name="archive" size={14} tone="inherit" className="text-cyan-300" />
          <p className="min-w-0 flex-1 text-[12.5px] text-tx-dim">
            {backingUp ? "Backing up your world — you can apply once it finishes."
              : last ? <>Last world backup <strong className="font-semibold text-white">{last.toLocaleString()}</strong>{recent ? "" : " — consider a fresh one"}</>
              : "No world backup from this panel yet."}
          </p>
          <button type="button" onClick={startBackup} disabled={backingUp || !!ov.job || !ov.serverRunning} className="rounded-[10px] border border-cyan-400/40 bg-cyan-400/10 px-3 py-1.5 text-[12px] font-semibold text-cyan-100 transition hover:bg-cyan-400/20 disabled:opacity-50">
            {backingUp ? "Backing up…" : "Back up world first"}
          </button>
        </div>
        {backupErr && <p className="mt-1.5 text-[12px] text-red-300">{backupErr}</p>}
      </div>
      <label className="mt-3 flex cursor-pointer items-start gap-2 text-[12.5px] leading-relaxed text-white">
        <input type="checkbox" checked={ack} onChange={(e) => setAck(e.target.checked)} className="mt-0.5" />
        <span>I understand content these mods added may be deleted from the world while they&apos;re off, and turning them back on won&apos;t restore it.</span>
      </label>
      <div className="mt-4 flex flex-wrap gap-2.5">
        <button type="button" onClick={onConfirm} disabled={!ack || backingUp || !!ov.job} className="nx-cta px-5 py-2.5 text-[13px] disabled:opacity-50">Apply changes</button>
        <button type="button" onClick={onCancel} className="rounded-[11px] border border-rim-hi bg-well px-4 py-2.5 text-[13px] font-semibold text-tx-dim transition hover:text-white">Cancel</button>
      </div>
    </Modal>
  );
}

