body='''export function ModsPanel({ serverId, scope }: { serverId: string; scope: "mods" | "plugins" }) {
  const [ov, setOv] = useState<ModsOverview | null>(null);
  const [fatal, setFatal] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [area, setArea] = useState<Area | null>(null);
  const [total, setTotal] = useState<number | null>(null);
  const [refreshKey, setRefreshKey] = useState(0);
  const [confirm, setConfirm] = useState<InstallTarget | null>(null);
  const [removing, setRemoving] = useState<InstalledMod | null>(null);
  const [riskBatch, setRiskBatch] = useState<{ changes: { modId: string; op: StagedOp }[]; risky: InstalledMod[] } | null>(null);
  const [updates, setUpdates] = useState<Record<string, string | null> | null>(null);
  const [checking, setChecking] = useState(false);
  const [restarting, setRestarting] = useState(false);
  const [, start] = useTransition();

  const loadOverview = useCallback(async () => {
    const r = await getModsOverview(serverId).catch(() => ({ error: "Couldn't load your mods." }) as { error: string });
    if ("view" in r && r.view) {
      setOv(r.view);
      setFatal(null);
    } else if ("error" in r && r.error) setFatal(r.error);
  }, [serverId]);

  useEffect(() => { void loadOverview(); }, [loadOverview]);

  // First view: the library when there is one, the store when there isn't.
  useEffect(() => {
    if (ov && area === null) setArea(ov.installed.some((m) => m.status !== "REMOVED") ? "installed" : "store");
  }, [ov, area]);

  // Plugins view = the catalogue's admin-ish categories (a filter, said plainly).
  const pluginCategory = useMemo(() => {
    if (scope !== "plugins" || !ov) return null;
    return ov.categories.find((c) => PLUGIN_CATS.some((k) => c.category.toLowerCase().includes(k)))?.category ?? null;
  }, [scope, ov]);

  // Follow the job while one is queued/running, then refresh the store's results once.
  const active = !!ov?.job || (ov?.installed ?? []).some((m) => m.status && PENDING.has(m.status));
  const wasActive = useRef(false);
  useEffect(() => {
    if (!active) {
      if (wasActive.current) {
        wasActive.current = false;
        setRefreshKey((k) => k + 1);
      }
      return;
    }
    wasActive.current = true;
    const t = setInterval(() => void loadOverview(), 3000);
    return () => clearInterval(t);
  }, [active, loadOverview]);

  const run = (fn: () => Promise<{ error?: string } | null | undefined>, ok?: string) =>
    start(async () => {
      setError(null);
      setNotice(null);
      const r = await fn().catch(() => ({ error: "Couldn't reach the server." }));
      if (r && r.error) setError(r.error);
      else if (ok) setNotice(ok);
      await loadOverview();
      setRefreshKey((k) => k + 1);
    });

  const install = (m: InstallTarget, ackClient: boolean) => {
    setConfirm(null);
    run(() => panelInstallMod(serverId, m.id, { ackClient }), `Installing ${m.name} — it will appear under Installed mods.`);
  };
  const applyBatch = (changes: { modId: string; op: StagedOp }[], ackRisk: boolean) => {
    setRiskBatch(null);
    run(() => panelApplyModBatch(serverId, changes, { ackRisk }));
  };

  const restartNow = () =>
    start(async () => {
      setRestarting(true);
      setError(null);
      const r = await gamePower(serverId, "restart").catch(() => ({ ok: false as const, error: "Couldn't reach the server." }));
      if (!r.ok) setError(r.error);
      await loadOverview();
      setRestarting(false);
    });

  const doCheckUpdates = () =>
    start(async () => {
      setChecking(true);
      const r = await checkModUpdates(serverId).catch(() => ({ error: "Couldn't check for updates." }) as { error: string });
      if ("updates" in r && r.updates) setUpdates(r.updates);
      else if ("error" in r && r.error) setError(r.error);
      setChecking(false);
    });

  if (!ov && !fatal) {
    return <div className="rounded-[16px] border border-rim-hi bg-well px-6 py-16 text-center text-[13px] text-tx-dim">Loading mods…</div>;
  }
  if (!ov) {
    return (
      <div className="rounded-[16px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-6 py-14 text-center">
        <Icon name="cube" size={28} className="mx-auto" />
        <p className="mt-3 text-[14.5px] font-bold text-white">Mods aren&apos;t available for this game</p>
        <p className="mx-auto mt-1.5 max-w-[52ch] text-[12.5px] leading-relaxed text-tx-dim">{fatal}</p>
      </div>
    );
  }

  const unavailable = ov.coverage.mode === "unavailable";
  const installedVisible = ov.installed.filter((m) => m.status !== "REMOVED");
  const enabledCount = installedVisible.filter((m) => m.status === "INSTALLED").length;
  const disabledCount = installedVisible.filter((m) => m.status === "DISABLED").length;
  const cur: Area = area ?? "installed";

  return (
    <div className="flex flex-col gap-4">
      {/* ── banner ───────────────────────────────────────────────────── */}
      <div className="nx-dark-island overflow-hidden rounded-[17px] border border-[#7b3fef]/40 bg-[linear-gradient(140deg,rgba(90,40,200,.35),rgba(20,36,110,.28)_58%,rgba(4,12,34,.5))] p-4 sm:p-5">
        <div className="flex flex-wrap items-start gap-4 sm:gap-5">
          <span className="grid h-[48px] w-[48px] flex-none place-items-center rounded-[14px] border border-white/15 bg-white/10">
            <Icon name="cube" size={21} tone="inherit" className="text-fuchsia-300" />
          </span>
          <div className="min-w-0 flex-1">
            <div className="flex flex-wrap items-center gap-2">
              <h2 className="text-[19px] font-extrabold tracking-[-0.02em] text-white">Mods &amp; Plugins</h2>
              {unavailable ? (
                <Chip cls="border-white/20 bg-white/[0.07] text-white/70">Manual install</Chip>
              ) : !ov.installsLive ? (
                <Chip cls="border-amber-400/45 bg-amber-400/10 text-amber-200" icon="lock">One-click paused</Chip>
              ) : (
                <Chip cls="border-cyan-400/40 bg-cyan-400/10 text-cyan-200" icon="bolt">One-click</Chip>
              )}
            </div>
            <p className="mt-1.5 max-w-[68ch] text-[12.5px] leading-relaxed text-white/75">
              {unavailable
                ? ov.coverage.text
                : <>Your installed mods and the full {ov.familyName} store in one place. {ov.coverage.mode === "engine" ? <>We fetch the right build for your server from the mod&apos;s own source, check it, pull in its dependencies and back up anything it changes. </> : null}<span className="text-white/55">{ov.coverage.text}</span></>}
            </p>
            <p className="mt-2 flex flex-wrap items-center gap-2 text-[11.5px] text-white/60">
              <span className="rounded-[6px] border border-white/15 bg-white/[0.07] px-2 py-0.5 font-semibold text-white/85">
                {ov.variant ?? "server"}{ov.gameVersion ? ` · ${ov.gameVersion}` : ""}
              </span>
              compatibility is checked against this
            </p>
          </div>
          <dl className="flex flex-none gap-6">
            <div className="flex flex-col">
              <dt className="text-[10px] font-bold uppercase tracking-[0.14em] text-white/50">Enabled</dt>
              <dd className="num text-[22px] font-extrabold leading-none text-white">{enabledCount}</dd>
            </div>
            {disabledCount > 0 && (
              <div className="flex flex-col">
                <dt className="text-[10px] font-bold uppercase tracking-[0.14em] text-white/50">Off</dt>
                <dd className="num text-[22px] font-extrabold leading-none text-white/70">{disabledCount}</dd>
              </div>
            )}
            <div className="flex flex-col">
              <dt className="text-[10px] font-bold uppercase tracking-[0.14em] text-white/50">In store</dt>
              <dd className="num text-[22px] font-extrabold leading-none text-white">{ov.catalogTotal.toLocaleString()}</dd>
            </div>
          </dl>
        </div>
      </div>

      {!unavailable && !ov.installsLive && (
        <div className="flex items-start gap-3 rounded-[14px] border border-amber-500/40 bg-amber-500/[0.08] px-4 py-3.5" role="status">
          <Icon name="lock" size={15} tone="inherit" className="mt-0.5 text-amber-300" />
          <div className="min-w-0 text-[12.5px] leading-relaxed text-amber-100/90">
            <p className="font-bold text-amber-200">One-click mod changes aren&apos;t switched on yet</p>
            <p className="mt-0.5">You can browse the store and see what&apos;s installed, but installing, updating, switching off or removing from here is paused — nothing would be applied. Add mods by hand in the <strong className="font-semibold">Files</strong> tab meanwhile.</p>
          </div>
        </div>
      )}

      {/* ── job progress ─────────────────────────────────────────────── */}
      {ov.job && (
        <div className="rounded-[14px] border border-sky-500/35 bg-sky-500/[0.07] px-4 py-3" role="status" aria-live="polite">
          <div className="flex items-center gap-2.5">
            <Icon name="refresh" size={14} tone="inherit" className="animate-spin text-sky-300" />
            <p className="min-w-0 flex-1 truncate text-[12.5px] font-semibold text-sky-200">
              {ov.job.status === "QUEUED" ? "Queued — waiting for the server to be free" : ov.backupRunning ? "Backing up your world…" : ov.job.step ?? "Working…"}
            </p>
            <span className="num text-[12px] font-bold text-sky-300">{ov.job.progress}%</span>
          </div>
          <div className="mt-2 h-[5px] overflow-hidden rounded-full bg-white/[0.08]">
            <div className="h-full rounded-full bg-[linear-gradient(90deg,#3b6be8,#7b3fef)] transition-all duration-700" style={{ width: `${Math.max(4, ov.job.progress)}%` }} />
          </div>
        </div>
      )}

      {/* ── restart prompt ───────────────────────────────────────────── */}
      {!ov.job && ov.restart.required && (
        <div className="flex flex-wrap items-center gap-3 rounded-[14px] border border-amber-500/45 bg-amber-500/[0.09] px-4 py-3.5" role="status">
          <Icon name="warntriangle" size={16} tone="inherit" className="text-amber-300" />
          <div className="min-w-0 flex-1">
            <p className="text-[13px] font-bold text-amber-200">Restart required to load your mod changes</p>
            {ov.restart.changed.length > 0 && (
              <p className="mt-0.5 line-clamp-2 text-[12px] text-amber-200/75">{ov.restart.changed.slice(0, 6).join(" · ")}</p>
            )}
          </div>
          <button type="button" onClick={restartNow} disabled={restarting || !ov.serverRunning} className="nx-cta px-4 py-2 text-[12.5px] disabled:opacity-50">
            {restarting ? "Restarting…" : "Restart now"}
          </button>
        </div>
      )}

      <LoadBanner load={ov.load} />

      {error && <p className="rounded-[11px] border border-red-500/35 bg-red-500/10 px-3.5 py-2.5 text-[12.5px] text-red-300" role="alert">{error}</p>}
      {notice && !error && <p className="rounded-[11px] border border-emerald-500/30 bg-emerald-500/[0.08] px-3.5 py-2.5 text-[12.5px] text-emerald-200" role="status">{notice}</p>}

      {/* ── the two areas ────────────────────────────────────────────── */}
      <div className="grid grid-cols-2 gap-2 sm:flex sm:gap-2.5" role="tablist" aria-label="Mods">
        {([
          ["installed", "layers", "Installed mods", `${installedVisible.length} on this server`],
          ["store", "cart", "Mod store", total === null ? `${ov.catalogTotal.toLocaleString()} for ${ov.familyName}` : `${total.toLocaleString()} match`],
        ] as const).map(([k, icon, label, sub]) => (
          <button key={k} type="button" role="tab" aria-selected={cur === k} onClick={() => setArea(k)}
            className={"flex min-w-0 items-center gap-2.5 rounded-[13px] border px-3.5 py-2.5 text-left transition sm:min-w-[210px] " + (cur === k ? "border-[#7b3fef]/60 bg-[linear-gradient(140deg,rgba(123,63,239,.28),rgba(59,107,232,.14))] shadow-[0_10px_30px_-18px_rgba(123,63,239,.9)]" : "border-rim-hi bg-[rgba(6,14,36,.6)] hover:border-brand-400/40")}>
            <span className={"grid h-[30px] w-[30px] flex-none place-items-center rounded-[9px] border " + (cur === k ? "border-white/20 bg-white/10 text-cyan-200" : "border-rim-hi bg-well text-tx-dim")}>
              <Icon name={icon} size={14} tone="inherit" />
            </span>
            <span className="min-w-0">
              <span className={"block truncate text-[13px] font-bold " + (cur === k ? "text-white" : "text-tx-dim")}>{label}</span>
              <span className="block truncate text-[11px] text-tx-faint">{sub}</span>
            </span>
          </button>
        ))}
      </div>

      {cur === "installed" ? (
        <InstalledLibrary
          ov={ov}
          busy={!!ov.job}
          updates={updates}
          checking={checking}
          onCheckUpdates={doCheckUpdates}
          onUpdate={(m) => run(() => panelUpdateMod(serverId, m.id), `Updating ${m.name}…`)}
          onRemove={(m) => setRemoving(m)}
          onApply={(changes, risky) => (risky.length ? setRiskBatch({ changes, risky }) : applyBatch(changes, false))}
        />
      ) : (
        <ModBrowser
          serverId={serverId}
          scope={scope}
          unavailable={unavailable}
          jobActive={!!ov.job || !ov.installsLive}
          refreshKey={refreshKey}
          defaultCategory={pluginCategory}
          catalogTotal={ov.catalogTotal}
          onInstall={(m) => setConfirm(fromCard(m))}
          onAct={(modId, op) => {
            if (op === "remove") run(() => panelRemoveMod(serverId, modId));
            else if (op === "update") run(() => panelUpdateMod(serverId, modId));
            else if (op === "enable" || op === "disable") setArea("installed");
          }}
          onTotal={setTotal}
        />
      )}

      <p className="text-[11.5px] leading-relaxed text-tx-faint">
        Anything not in the store can still be installed by hand: upload it in the <strong className="text-tx-dim">Files</strong> tab and restart from <strong className="text-tx-dim">Console</strong>. Before changing files we keep a backup on your server in <span className="font-mono text-tx-dim">/root/.nxeon-mods/backups</span>.
      </p>

