        <RemoveDialog m={removing} onCancel={() => setRemoving(null)}
          onConfirm={() => { const m = removing; setRemoving(null); run(() => panelRemoveMod(serverId, m.id), `Removing ${m.name}…`); }} />
      )}
      {riskBatch && (
        <RiskDialog
          serverId={serverId}
          ov={ov}
          risky={riskBatch.risky}
          count={riskBatch.changes.length}
          onCancel={() => setRiskBatch(null)}
          onConfirm={() => applyBatch(riskBatch.changes, true)}
          onBackedUp={() => void loadOverview()}
        />
      )}
