function Modal({ label, onCancel, children }: { label: string; onCancel: () => void; children: React.ReactNode }) {
  useEffect(() => {
    const k = (e: KeyboardEvent) => e.key === "Escape" && onCancel();
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [onCancel]);
  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-black/65 p-4 backdrop-blur-sm" role="dialog" aria-modal="true" aria-label={label} onClick={(e) => e.target === e.currentTarget && onCancel()}>
      <div className="nx-dark-island max-h-[88vh] w-full max-w-[500px] overflow-y-auto rounded-[17px] border border-[#7b3fef]/40 bg-[linear-gradient(180deg,rgba(14,26,56,.97),rgba(3,9,24,.98))] p-5">{children}</div>
    </div>
  );
}

function RemoveDialog({ m, onCancel, onConfirm }: { m: InstalledMod; onCancel: () => void; onConfirm: () => void }) {
  return (
    <Modal label={`Uninstall ${m.name}`} onCancel={onCancel}>
      <div className="flex items-start gap-3">
