}

/**
 * Pre-change prompt for disabling content-adding mods: says exactly what can
 * be lost, offers a world backup FIRST (a real GAME_BACKUP job), and only
 * enables Apply once the owner ticks the acknowledgement. The server action
 * refuses the same change without that acknowledgement.
 */
function RiskDialog({ serverId, ov, risky, count, onCancel, onConfirm, onBackedUp }: {
  serverId: string; ov: ModsOverview; risky: InstalledMod[]; count: number; onCancel: () => void; onConfirm: () => void; onBackedUp: () => void;
}) {
  const [ack, setAck] = useState(false);
  const [backup, setBackup] = useState<"idle" | "queued" | "error">("idle");
  const [backupErr, setBackupErr] = useState<string | null>(null);
  const backingUp = backup === "queued" || ov.backupRunning;
  const startBackup = async () => {
    setBackupErr(null);
    const r = await createGameBackup(serverId).catch(() => ({ ok: false as const, error: "Couldn't reach the server." }));
    if (r.ok) { setBackup("queued"); onBackedUp(); }
    else { setBackup("error"); setBackupErr(r.error); }
  };
  const last = ov.lastWorldBackupAt ? new Date(ov.lastWorldBackupAt) : null;
  const recent = !!last && Date.now() - last.getTime() < 2 * 3600_000;
  return (
    <Modal label="Confirm disabling mods that add content" onCancel={onCancel}>
      <div className="flex items-start gap-3">
        <span className="grid h-[40px] w-[40px] flex-none place-items-center rounded-[12px] border border-amber-500/40 bg-amber-500/10 text-amber-300"><Icon name="warntriangle" size={17} tone="inherit" /></span>
        <div className="min-w-0">
          <h3 className="text-[15.5px] font-extrabold text-white">Some of these add things to your world</h3>
          <p className="mt-0.5 text-[12px] text-tx-faint">{count} change{count === 1 ? "" : "s"} ready to apply</p>
        </div>
      </div>
      <ul className="mt-4 flex flex-col gap-2">
        {risky.map((m) => (
          <li key={m.id} className="rounded-[11px] border border-amber-500/30 bg-amber-500/[0.06] px-3 py-2.5 text-[12.5px] leading-relaxed text-amber-100/90">
            <strong className="font-bold text-amber-200">{m.name}</strong>
            <span className="block text-[12px] text-amber-100/75">{m.toggle.allowed ? m.toggle.warning : null}</span>
          </li>
        ))}
      </ul>
      <div className="mt-3 rounded-[12px] border border-rim-hi bg-well px-3.5 py-3">
        <div className="flex flex-wrap items-center gap-2.5">
          <Icon name="archive" size={14} tone="inherit" className="text-cyan-300" />
          <p className="min-w-0 flex-1 text-[12.5px] text-tx-dim">
            {backingUp ? "Backing up your world — you can apply once it finishes."
              : last ? <>Last world backup <strong className="font-semibold text-white">{last.toLocaleString()}</strong>{recent ? "" : " — consider a fresh one"}</>
              : "No world backup from this panel yet."}
          </p>
          <button type="button" onClick={startBackup} disabled={backingUp || !!ov.job || !ov.serverRunning} className="rounded-[10px] border border-cyan-400/40 bg-cyan-400/10 px-3 py-1.5 text-[12px] font-semibold text-cyan-100 transition hover:bg-cyan-400/20 disabled:opacity-50">
            {backingUp ? "Backing up…" : "Back up world first"}
          </button>
        </div>
        {backupErr && <p className="mt-1.5 text-[12px] text-red-300">{backupErr}</p>}
      </div>
      <label className="mt-3 flex cursor-pointer items-start gap-2 text-[12.5px] leading-relaxed text-white">
        <input type="checkbox" checked={ack} onChange={(e) => setAck(e.target.checked)} className="mt-0.5" />
        <span>I understand content these mods added may be deleted from the world while they&apos;re off, and turning them back on won&apos;t restore it.</span>
      </label>
      <div className="mt-4 flex flex-wrap gap-2.5">
        <button type="button" onClick={onConfirm} disabled={!ack || backingUp || !!ov.job} className="nx-cta px-5 py-2.5 text-[13px] disabled:opacity-50">Apply changes</button>
        <button type="button" onClick={onCancel} className="rounded-[11px] border border-rim-hi bg-well px-4 py-2.5 text-[13px] font-semibold text-tx-dim transition hover:text-white">Cancel</button>
      </div>
    </Modal>
  );
}

