cat > /tank/nxeon-wt-mods/.agt/shots.mjs <<'EOF'
import { chromium } from "/opt/nxeon/node_modules/playwright/index.mjs";
import fs from "node:fs";
const S = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad";
const OUT = "/root/agent-notes/mods-rework";
const seed = JSON.parse(fs.readFileSync(`${S}/mods-seed-out.txt`, "utf8").trim().split("\n").pop());
const base = "http://localhost:3127";
const browser = await chromium.launch();
const errors = [];
const go = async (ctx, id, label) => {
  const page = await ctx.newPage();
  page.on("pageerror", (e) => errors.push(`${label}: ${e.message}`));
  page.on("console", (m) => { if (m.type() === "error") errors.push(`${label} console: ${m.text().slice(0, 240)}`); });
  await page.goto(`${base}/dashboard/servers/${id}?tab=mods`, { waitUntil: "networkidle", timeout: 300_000 });
  await page.waitForTimeout(2500);
  for (const t of ["Skip", "Not now", "Close"]) { const b = page.getByRole("button", { name: t }); if (await b.count()) await b.first().click().catch(() => {}); }
  return page;
};
for (const [vpName, vp] of [["1440", { width: 1440, height: 1100 }], ["390", { width: 390, height: 844 }]]) {
  const ctx = await browser.newContext({ viewport: vp });
  await ctx.addCookies([{ name: seed.cookie, value: seed.token, domain: "localhost", path: "/" }]);
  // Fabric: installed library
  let p = await go(ctx, seed.fab, `fabric-${vpName}`);
  await p.getByRole("tab", { name: /Installed mods/ }).click().catch(() => {});
  await p.waitForTimeout(800);
  const ov = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
  console.log(JSON.stringify({ vpName, overflowPx: ov, switches: await p.getByRole("switch").count() }));
  await p.screenshot({ path: `${OUT}/installed-fabric-${vpName}.png`, fullPage: true });
  // stage: disable Create (content, needed? no) + disable Fabric API (needed by Create → problem)
  await p.getByRole("switch", { name: "Disable Fabric API" }).click();
  await p.waitForTimeout(400);
  await p.screenshot({ path: `${OUT}/staged-dependency-problem-fabric-${vpName}.png`, fullPage: true });
  await p.getByRole("switch", { name: "Disable Create Fabric" }).click();
  await p.waitForTimeout(400);
  // Fabulously Optimized also needs Fabric API → still a problem; reset Fabric API
  await p.getByRole("switch", { name: "Enable Fabric API" }).click();
  await p.getByRole("switch", { name: "Enable Waystones" }).click();
  await p.waitForTimeout(400);
  await p.screenshot({ path: `${OUT}/staged-ok-fabric-${vpName}.png`, fullPage: true });
  await p.getByRole("button", { name: "Apply changes" }).first().click();
  await p.waitForTimeout(900);
  await p.screenshot({ path: `${OUT}/risk-dialog-fabric-${vpName}.png`, fullPage: false });
  await p.keyboard.press("Escape");
  // store
  await p.getByRole("tab", { name: /Mod store/ }).click();
  await p.waitForTimeout(3000);
  await p.screenshot({ path: `${OUT}/store-fabric-${vpName}.png`, fullPage: false });
  await p.close();
  // Paper: SAFE + health
  p = await go(ctx, seed.pap, `paper-${vpName}`);
  await p.screenshot({ path: `${OUT}/installed-paper-health-${vpName}.png`, fullPage: true });
  await p.getByRole("button", { name: "Uninstall" }).first().click();
  await p.waitForTimeout(500);
  await p.screenshot({ path: `${OUT}/uninstall-dialog-paper-${vpName}.png`, fullPage: false });
  await p.close();
  await ctx.close();
}
await browser.close();
console.log("ERRORS", JSON.stringify(errors, null, 1));
EOF
sleep 30; tail -5 /tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/mods-dev.log

